import { describe, expect, test } from 'bun:test'
import {
  SETTING_SOURCE_TO_SCOPE,
  buildPluginId,
  isOfficialMarketplaceName,
  parsePluginIdentifier,
  scopeToSettingSource,
  settingSourceToScope,
} from '../plugin/pluginIdentifier.js'

describe('parsePluginIdentifier', () => {
  test('plugin name only → name without marketplace', () => {
    expect(parsePluginIdentifier('foo')).toEqual({ name: 'foo' })
  })

  test('plugin@marketplace → split on first @', () => {
    expect(parsePluginIdentifier('foo@bar')).toEqual({
      name: 'foo',
      marketplace: 'bar',
    })
  })

  test('multiple @ — only first split (rest absorbed/ignored)', () => {
    // Documented: 'plugin@market@place' → name='plugin', marketplace='market'.
    // Anything after second @ is silently dropped because parts[1] takes
    // only the second segment.
    expect(parsePluginIdentifier('plugin@market@place')).toEqual({
      name: 'plugin',
      marketplace: 'market',
    })
  })

  test('empty plugin name with @ → name="" (parts[0] || "")', () => {
    // '@market' → split = ['', 'market']. The `|| ''` keeps name empty.
    expect(parsePluginIdentifier('@market')).toEqual({
      name: '',
      marketplace: 'market',
    })
  })

  test('plugin@ (trailing @) → empty marketplace string', () => {
    // 'foo@' → split = ['foo', '']. marketplace is empty string, NOT
    // undefined. Documents this — caller distinguishing "no marketplace"
    // vs "empty marketplace" must check truthy explicitly.
    expect(parsePluginIdentifier('foo@')).toEqual({
      name: 'foo',
      marketplace: '',
    })
  })

  test('empty string → empty name', () => {
    expect(parsePluginIdentifier('')).toEqual({ name: '' })
  })

  test('only @ → empty name + empty marketplace', () => {
    expect(parsePluginIdentifier('@')).toEqual({
      name: '',
      marketplace: '',
    })
  })

  test('hyphenated names work', () => {
    expect(parsePluginIdentifier('my-plugin@my-market')).toEqual({
      name: 'my-plugin',
      marketplace: 'my-market',
    })
  })

  test('underscore + dot in name preserved', () => {
    expect(parsePluginIdentifier('my_plugin.v2@market')).toEqual({
      name: 'my_plugin.v2',
      marketplace: 'market',
    })
  })
})

describe('buildPluginId — inverse of parsePluginIdentifier', () => {
  test('without marketplace → just name', () => {
    expect(buildPluginId('foo')).toBe('foo')
  })

  test('with marketplace → name@marketplace', () => {
    expect(buildPluginId('foo', 'bar')).toBe('foo@bar')
  })

  test('undefined marketplace → just name', () => {
    expect(buildPluginId('foo', undefined)).toBe('foo')
  })

  test('empty string marketplace → just name (treated as missing via ternary)', () => {
    // CRITICAL: the function uses `marketplace ? "name@marketplace" : name`.
    // Empty string is falsy → drops the @ separator. This means
    // parsePluginIdentifier('foo@') → buildPluginId('foo', '') → 'foo' is
    // NOT a round-trip identity. Document this.
    expect(buildPluginId('foo', '')).toBe('foo')
  })

  test('round-trip: parse → build (canonical case)', () => {
    expect(buildPluginId('a', 'b')).toBe('a@b')
    const p = parsePluginIdentifier('a@b')
    expect(buildPluginId(p.name, p.marketplace)).toBe('a@b')
  })

  test('round-trip with empty marketplace — string gets normalized', () => {
    // 'foo@' → parse → {name: 'foo', marketplace: ''} → build → 'foo'.
    // The empty marketplace gets dropped on rebuild. Document the
    // asymmetry.
    const p = parsePluginIdentifier('foo@')
    expect(buildPluginId(p.name, p.marketplace)).toBe('foo')
  })
})

describe('isOfficialMarketplaceName — security boundary', () => {
  // CRITICAL: this gate determines whether marketplace names go to general
  // analytics (safe — opensource Anthropic-controlled names) or PII-tagged
  // BQ columns (third-party names, possibly identifying). A leak here
  // would put third-party names into general analytics by mistake.

  test('undefined → false (no-marketplace plugins)', () => {
    expect(isOfficialMarketplaceName(undefined)).toBe(false)
  })

  test('empty string → false', () => {
    expect(isOfficialMarketplaceName('')).toBe(false)
  })

  test('claude-code-marketplace → true', () => {
    expect(isOfficialMarketplaceName('claude-code-marketplace')).toBe(true)
  })

  test('claude-code-plugins → true', () => {
    expect(isOfficialMarketplaceName('claude-code-plugins')).toBe(true)
  })

  test('claude-plugins-official → true', () => {
    expect(isOfficialMarketplaceName('claude-plugins-official')).toBe(true)
  })

  test('anthropic-marketplace → true', () => {
    expect(isOfficialMarketplaceName('anthropic-marketplace')).toBe(true)
  })

  test('anthropic-plugins → true', () => {
    expect(isOfficialMarketplaceName('anthropic-plugins')).toBe(true)
  })

  test('agent-skills → true', () => {
    expect(isOfficialMarketplaceName('agent-skills')).toBe(true)
  })

  test('case-insensitive matching (CLAUDE-CODE-PLUGINS → true)', () => {
    // The check uses `.toLowerCase()`. Verify upstream/uppercase variants.
    expect(isOfficialMarketplaceName('CLAUDE-CODE-PLUGINS')).toBe(true)
  })

  test('mixed case accepted', () => {
    expect(isOfficialMarketplaceName('Claude-Code-Plugins')).toBe(true)
  })

  test('third-party name → false (security boundary)', () => {
    expect(isOfficialMarketplaceName('third-party-marketplace')).toBe(false)
  })

  test('typo of official name → false', () => {
    // CRITICAL: a near-miss like 'antrhopic-marketplace' (typo) MUST
    // still be classified as third-party. The Set membership check is
    // exact (after lowercase) — no fuzzy match.
    expect(isOfficialMarketplaceName('antrhopic-marketplace')).toBe(false)
  })

  test('substring of official name → false', () => {
    expect(isOfficialMarketplaceName('claude-code')).toBe(false)
  })

  test('superstring of official name → false', () => {
    expect(isOfficialMarketplaceName('claude-code-marketplace-fake')).toBe(false)
  })

  test('whitespace-padded official name → false (no trim)', () => {
    // Documents: the function does NOT trim. ' claude-code-plugins ' is
    // NOT recognized as official.
    expect(isOfficialMarketplaceName(' claude-code-plugins ')).toBe(false)
  })
})

describe('scopeToSettingSource — install scope routing', () => {
  test('user → userSettings', () => {
    expect(scopeToSettingSource('user')).toBe('userSettings')
  })

  test('project → projectSettings', () => {
    expect(scopeToSettingSource('project')).toBe('projectSettings')
  })

  test('local → localSettings', () => {
    expect(scopeToSettingSource('local')).toBe('localSettings')
  })

  test('managed scope throws (cannot install)', () => {
    // CRITICAL: managed scope is policy-pushed by the IT admin and is
    // read-only at the CLI level. Throwing here prevents install paths
    // from accidentally writing to it.
    expect(() => scopeToSettingSource('managed')).toThrow(
      /Cannot install plugins to managed scope/,
    )
  })
})

describe('settingSourceToScope — inverse of scopeToSettingSource', () => {
  test('userSettings → user', () => {
    expect(settingSourceToScope('userSettings')).toBe('user')
  })

  test('projectSettings → project', () => {
    expect(settingSourceToScope('projectSettings')).toBe('project')
  })

  test('localSettings → local', () => {
    expect(settingSourceToScope('localSettings')).toBe('local')
  })

  test('flagSettings → flag (session-only, NOT persisted)', () => {
    // 'flag' scope is session-only — it's the --plugin-dir CLI flag.
    // Persistence layer must filter this out before writing
    // installed_plugins.json. Documents the existence of this fourth
    // scope value.
    // settingSourceToScope no admite 'flagSettings': su parámetro es
    // EditableSettingSource, que lo excluye a propósito. Se lee el mapa
    // del que la función deriva en vez de forzar el tipo con `as never`.
    expect(SETTING_SOURCE_TO_SCOPE.flagSettings).toBe('flag')
  })
})

// El conjunto de mercados oficiales del binario 2.1.275, verbatim. thyrox
// declaraba 8 de 14; cualquier nombre que falte aquí deja de reconocerse como
// oficial, que es una frontera de seguridad.
const BINARY_OFFICIAL_MARKETPLACES = [
  'claude-code-marketplace', 'claude-code-plugins', 'claude-plugins-official',
  'anthropic-marketplace', 'anthropic-plugins', 'agent-skills',
  'anthropic-agent-skills', 'life-sciences', 'knowledge-work-plugins',
  'claude-for-legal', 'claude-for-financial-services',
  'financial-services-plugins', 'first-party-plugins', 'claude-tag-plugins',
]

describe('isOfficialMarketplaceName — el conjunto del binario 2.1.275', () => {
  for (const name of BINARY_OFFICIAL_MARKETPLACES) {
    test(`${name} es oficial`, () => {
      expect(isOfficialMarketplaceName(name)).toBe(true)
    })
  }
})

/**
 * Plugin installation for headless/CCR mode.
 *
 * This module provides plugin installation without AppState updates,
 * suitable for non-interactive environments like CCR.
 *
 * When CLAUDE_CODE_PLUGIN_USE_ZIP_CACHE is enabled, plugins are stored as
 * ZIPs on a mounted volume. The storage layer (pluginLoader.ts) handles
 * ZIP creation on install and extraction on load transparently.
 */

import { logEvent } from '@thyrox/local-observability'
import { registerCleanup } from './_deps.js'
import { logForDebugging } from './_deps.js'
import { withDiagnosticsTiming } from './_deps.js'
import { getFsImplementation } from './_deps.js'
import { logError } from './_deps.js'
import {
  clearMarketplacesCache,
  getDeclaredMarketplaces,
  registerSeedMarketplaces,
} from './marketplaceManager.js'
import { detectAndUninstallDelistedPlugins } from './pluginBlocklist.js'
import { clearPluginCache } from './pluginLoader.js'
import { reconcileMarketplaces } from './reconciler.js'
import {
  cleanupSessionPluginCache,
  getZipCacheMarketplacesDir,
  getZipCachePluginsDir,
  isMarketplaceSourceSupportedByZipCache,
  isPluginZipCacheEnabled,
} from './zipCache.js'
import { syncMarketplacesToZipCache } from './zipCacheAdapters.js'

/**
 * Install plugins for headless/CCR mode.
 *
 * This is the headless equivalent of performBackgroundPluginInstallations(),
 * but without AppState updates (no UI to update in headless mode).
 *
 * @returns true if any plugins were installed (caller should refresh MCP)
 */
export async function installPluginsForHeadless(): Promise<boolean> {
  const zipCacheMode = isPluginZipCacheEnabled()
  logForDebugging(
    `installPluginsForHeadless: starting${zipCacheMode ? ' (zip cache mode)' : ''}`,
  )

  // Register seed marketplaces (CLAUDE_CODE_PLUGIN_SEED_DIR) before diffing.
  // Idempotent; no-op if seed not configured. Without this, findMissingMarketplaces
  // would see seed entries as missing → clone → defeats seed's purpose.
  //
  // If registration changed state, clear caches so the early plugin-load pass
  // (which runs during CLI startup before this function) doesn't keep stale
  // "marketplace not found" results. Without this clear, a first-boot headless
  // run with a seed-cached plugin would show 0 plugin commands/agents/skills
  // in the init message even though the seed has everything.
  const seedChanged = await registerSeedMarketplaces()
  if (seedChanged) {
    clearMarketplacesCache()
    clearPluginCache('headlessPluginInstall: seed marketplaces registered')
  }

  // Ensure zip cache directory structure exists
  if (zipCacheMode) {
    await getFsImplementation().mkdir(getZipCacheMarketplacesDir())
    await getFsImplementation().mkdir(getZipCachePluginsDir())
  }

  // Declared now includes an implicit claude-plugins-official entry when any
  // enabled plugin references it (see getDeclaredMarketplaces). This routes
  // the official marketplace through the same reconciler path as any other —
  // which composes correctly with CLAUDE_CODE_PLUGIN_SEED_DIR: seed registers
  // it in known_marketplaces.json, reconciler diff sees it as upToDate, no clone.
  const declaredCount = Object.keys(getDeclaredMarketplaces()).length

  const metrics = {
    marketplaces_installed: 0,
    delisted_count: 0,
  }

  // Initialize from seedChanged so the caller (print.ts) calls
  // refreshPluginState() → clearCommandsCache/clearAgentDefinitionsCache
  // when seed registration added marketplaces. Without this, the caller
  // only refreshes when an actual plugin install happened.
  let pluginsChanged = seedChanged

  try {
    if (declaredCount === 0) {
      logForDebugging('installPluginsForHeadless: no marketplaces declared')
    } else {
      // Reconcile declared marketplaces (settings intent + implicit official)
      // with materialized state. Zip cache: skip unsupported source types.
      const reconcileResult = await withDiagnosticsTiming(
        'headless_marketplace_reconcile',
        () =>
          reconcileMarketplaces({
            skip: zipCacheMode
              ? (_name, source) =>
                  !isMarketplaceSourceSupportedByZipCache(source)
              : undefined,
            onProgress: event => {
              if (event.type === 'installed') {
                logForDebugging(
                  `installPluginsForHeadless: installed marketplace ${event.name}`,
                )
              } else if (event.type === 'failed') {
                logForDebugging(
                  `installPluginsForHeadless: failed to install marketplace ${event.name}: ${event.error}`,
                )
              }
            },
          }),
      )

      if (reconcileResult.skipped.length > 0) {
        logForDebugging(
          `installPluginsForHeadless: skipped ${reconcileResult.skipped.length} marketplace(s) unsupported by zip cache: ${reconcileResult.skipped.join(', ')}`,
        )
      }

      const marketplacesChanged =
        reconcileResult.installed.length + reconcileResult.updated.length

      // Clear caches so newly-installed marketplace plugins are discoverable.
      // Plugin caching is the loader's job — after caches clear, the caller's
      // refreshPluginState() → loadAllPlugins() will cache any missing plugins
      // from the newly-materialized marketplaces.
      if (marketplacesChanged > 0) {
        clearMarketplacesCache()
        clearPluginCache('headlessPluginInstall: marketplaces reconciled')
        pluginsChanged = true
      }

      metrics.marketplaces_installed = marketplacesChanged
    }

    // Zip cache: save marketplace JSONs for offline access on ephemeral containers.
    // Runs unconditionally so that steady-state containers (all plugins installed)
    // still sync marketplace data that may have been cloned in a previous run.
    if (zipCacheMode) {
      await syncMarketplacesToZipCache()
    }

    // Delisting enforcement
    const newlyDelisted = await detectAndUninstallDelistedPlugins()
    metrics.delisted_count = newlyDelisted.length
    if (newlyDelisted.length > 0) {
      pluginsChanged = true
    }

    if (pluginsChanged) {
      clearPluginCache('headlessPluginInstall: plugins changed')
    }

    // Zip cache: register session cleanup for extracted plugin temp dirs
    if (zipCacheMode) {
      registerCleanup(cleanupSessionPluginCache)
    }

    return pluginsChanged
  } catch (error) {
    logError(error)
    return false
  } finally {
    logEvent('tengu_headless_plugin_install', metrics)
  }
}

import memoize from 'lodash-es/memoize.js'
import { basename } from 'path'
import { isAutoMemoryEnabled } from '@thyrox/memory'
import type { AgentColorName } from './_deps.js'
import {
  type AgentMemoryScope,
  loadAgentMemoryPrompt,
} from '@thyrox/memory/agentMemory'
import type { AgentDefinition } from '@thyrox/tool-registry/tools/AgentTool/loadAgentsDir.js'
import { FILE_EDIT_TOOL_NAME } from './_deps.js'
import { FILE_READ_TOOL_NAME } from './_deps.js'
import { FILE_WRITE_TOOL_NAME } from './_deps.js'
import { getPluginErrorMessage } from './types.js'
import { logForDebugging } from './_deps.js'
import { EFFORT_LEVELS, parseEffortValue } from './_deps.js'
import {
  coerceDescriptionToString,
  parseFrontmatter,
  parsePositiveIntFromFrontmatter,
} from './_deps.js'
import { getFsImplementation, isDuplicatePath } from './_deps.js'
import {
  parseAgentToolsFromFrontmatter,
  parseSlashCommandToolsFromFrontmatter,
} from './_deps.js'
import { loadAllPluginsCacheOnly } from './pluginLoader.js'
import {
  loadPluginOptions,
  substitutePluginVariables,
  substituteUserConfigInContent,
} from './pluginOptionsStorage.js'
import type { PluginManifest } from './schemas.js'
import { walkPluginMarkdown } from './walkPluginMarkdown.js'

const VALID_MEMORY_SCOPES: AgentMemoryScope[] = ['user', 'project', 'local']

async function loadAgentsFromDirectory(
  agentsPath: string,
  pluginName: string,
  sourceName: string,
  pluginPath: string,
  pluginManifest: PluginManifest,
  loadedPaths: Set<string>,
): Promise<AgentDefinition[]> {
  const agents: AgentDefinition[] = []
  await walkPluginMarkdown(
    agentsPath,
    async (fullPath, namespace) => {
      const agent = await loadAgentFromFile(
        fullPath,
        pluginName,
        namespace,
        sourceName,
        pluginPath,
        pluginManifest,
        loadedPaths,
      )
      if (agent) agents.push(agent)
    },
    { logLabel: 'agents' },
  )
  return agents
}

async function loadAgentFromFile(
  filePath: string,
  pluginName: string,
  namespace: string[],
  sourceName: string,
  pluginPath: string,
  pluginManifest: PluginManifest,
  loadedPaths: Set<string>,
): Promise<AgentDefinition | null> {
  const fs = getFsImplementation()
  if (isDuplicatePath(filePath, loadedPaths)) {
    return null
  }
  try {
    const content = await fs.readFile(filePath, { encoding: 'utf-8' })
    const { frontmatter, content: markdownContent } = parseFrontmatter(
      content,
      filePath,
    )

    const baseAgentName =
      (frontmatter.name as string) || basename(filePath).replace(/\.md$/, '')

    // Apply namespace prefixing like we do for commands
    const nameParts = [pluginName, ...namespace, baseAgentName]
    const agentType = nameParts.join(':')

    // Parse agent metadata from frontmatter
    const whenToUse =
      coerceDescriptionToString(frontmatter.description, agentType) ??
      coerceDescriptionToString(frontmatter['when-to-use'], agentType) ??
      `Agent from ${pluginName} plugin`

    let tools = parseAgentToolsFromFrontmatter(frontmatter.tools)
    const skills = parseSlashCommandToolsFromFrontmatter(frontmatter.skills)
    const color = frontmatter.color as AgentColorName | undefined
    const modelRaw = frontmatter.model
    let model: string | undefined
    if (typeof modelRaw === 'string' && modelRaw.trim().length > 0) {
      const trimmed = modelRaw.trim()
      model = trimmed.toLowerCase() === 'inherit' ? 'inherit' : trimmed
    }
    const backgroundRaw = frontmatter.background
    const background =
      backgroundRaw === 'true' || backgroundRaw === true ? true : undefined
    // Substitute ${CLAUDE_PLUGIN_ROOT} so agents can reference bundled files,
    // and ${user_config.X} (non-sensitive only) so they can embed configured
    // usernames, endpoints, etc. Sensitive refs resolve to a placeholder.
    let systemPrompt = substitutePluginVariables(markdownContent.trim(), {
      path: pluginPath,
      source: sourceName,
    })
    if (pluginManifest.userConfig) {
      systemPrompt = substituteUserConfigInContent(
        systemPrompt,
        loadPluginOptions(sourceName),
        pluginManifest.userConfig,
      )
    }

    // Parse memory scope
    const memoryRaw = frontmatter.memory as string | undefined
    let memory: AgentMemoryScope | undefined
    if (memoryRaw !== undefined) {
      if (VALID_MEMORY_SCOPES.includes(memoryRaw as AgentMemoryScope)) {
        memory = memoryRaw as AgentMemoryScope
      } else {
        logForDebugging(
          `Plugin agent file ${filePath} has invalid memory value '${memoryRaw}'. Valid options: ${VALID_MEMORY_SCOPES.join(', ')}`,
        )
      }
    }

    // Parse isolation mode
    const isolationRaw = frontmatter.isolation as string | undefined
    const isolation =
      isolationRaw === 'worktree' ? ('worktree' as const) : undefined

    // Parse effort (string level or integer)
    const effortRaw = frontmatter.effort
    const effort =
      effortRaw !== undefined ? parseEffortValue(effortRaw) : undefined
    if (effortRaw !== undefined && effort === undefined) {
      logForDebugging(
        `Plugin agent file ${filePath} has invalid effort '${effortRaw}'. Valid options: ${EFFORT_LEVELS.join(', ')} or an integer`,
      )
    }

    // permissionMode, hooks, and mcpServers are intentionally NOT parsed for
    // plugin agents. Plugins are third-party marketplace code; these fields
    // escalate what the agent can do beyond what the user approved at install
    // time. For this level of control, define the agent in .claude/agents/
    // where the user explicitly wrote the frontmatter. (Note: plugins can
    // still ship hooks and MCP servers at the manifest level — that's the
    // install-time trust boundary. Per-agent declarations would let a single
    // agent file buried in agents/ silently add them.) See PR #22558 review.
    for (const field of ['permissionMode', 'hooks', 'mcpServers'] as const) {
      if (frontmatter[field] !== undefined) {
        logForDebugging(
          `Plugin agent file ${filePath} sets ${field}, which is ignored for plugin agents. Use .claude/agents/ for this level of control.`,
          { level: 'warn' },
        )
      }
    }

    // Parse maxTurns
    const maxTurnsRaw = frontmatter.maxTurns
    const maxTurns = parsePositiveIntFromFrontmatter(maxTurnsRaw)
    if (maxTurnsRaw !== undefined && maxTurns === undefined) {
      logForDebugging(
        `Plugin agent file ${filePath} has invalid maxTurns '${maxTurnsRaw}'. Must be a positive integer.`,
      )
    }

    // Parse disallowedTools
    const disallowedTools =
      frontmatter.disallowedTools !== undefined
        ? parseAgentToolsFromFrontmatter(frontmatter.disallowedTools)
        : undefined

    // If memory is enabled, inject Write/Edit/Read tools for memory access
    if (isAutoMemoryEnabled() && memory && tools !== undefined) {
      const toolSet = new Set(tools)
      for (const tool of [
        FILE_WRITE_TOOL_NAME,
        FILE_EDIT_TOOL_NAME,
        FILE_READ_TOOL_NAME,
      ]) {
        if (!toolSet.has(tool)) {
          tools = [...tools, tool]
        }
      }
    }

    return {
      agentType,
      whenToUse,
      tools,
      ...(disallowedTools !== undefined ? { disallowedTools } : {}),
      ...(skills !== undefined ? { skills } : {}),
      getSystemPrompt: () => {
        if (isAutoMemoryEnabled() && memory) {
          const memoryPrompt = loadAgentMemoryPrompt(agentType, memory)
          return systemPrompt + '\n\n' + memoryPrompt
        }
        return systemPrompt
      },
      source: 'plugin' as const,
      color,
      model,
      filename: baseAgentName,
      plugin: sourceName,
      ...(background ? { background } : {}),
      ...(memory ? { memory } : {}),
      ...(isolation ? { isolation } : {}),
      ...(effort !== undefined ? { effort } : {}),
      ...(maxTurns !== undefined ? { maxTurns } : {}),
    } as AgentDefinition
  } catch (error) {
    logForDebugging(`Failed to load agent from ${filePath}: ${error}`, {
      level: 'error',
    })
    return null
  }
}

export const loadPluginAgents = memoize(
  async (): Promise<AgentDefinition[]> => {
    // Only load agents from enabled plugins
    const { enabled, errors } = await loadAllPluginsCacheOnly()

    if (errors.length > 0) {
      logForDebugging(
        `Plugin loading errors: ${errors.map(e => getPluginErrorMessage(e)).join(', ')}`,
      )
    }

    // Process plugins in parallel; each plugin has its own loadedPaths scope
    const perPluginAgents = await Promise.all(
      enabled.map(async (plugin): Promise<AgentDefinition[]> => {
        // Track loaded file paths to prevent duplicates within this plugin
        const loadedPaths = new Set<string>()
        const pluginAgents: AgentDefinition[] = []

        // Load agents from default agents directory
        if (plugin.agentsPath) {
          try {
            const agents = await loadAgentsFromDirectory(
              plugin.agentsPath,
              plugin.name,
              plugin.source,
              plugin.path,
              plugin.manifest,
              loadedPaths,
            )
            pluginAgents.push(...agents)

            if (agents.length > 0) {
              logForDebugging(
                `Loaded ${agents.length} agents from plugin ${plugin.name} default directory`,
              )
            }
          } catch (error) {
            logForDebugging(
              `Failed to load agents from plugin ${plugin.name} default directory: ${error}`,
              { level: 'error' },
            )
          }
        }

        // Load agents from additional paths specified in manifest
        if (plugin.agentsPaths) {
          // Process all agentsPaths in parallel. isDuplicatePath is synchronous
          // (check-and-add), so concurrent access to loadedPaths is safe.
          const pathResults = await Promise.all(
            plugin.agentsPaths.map(
              async (agentPath): Promise<AgentDefinition[]> => {
                try {
                  const fs = getFsImplementation()
                  const stats = await fs.stat(agentPath)

                  if (stats.isDirectory()) {
                    // Load all .md files from directory
                    const agents = await loadAgentsFromDirectory(
                      agentPath,
                      plugin.name,
                      plugin.source,
                      plugin.path,
                      plugin.manifest,
                      loadedPaths,
                    )

                    if (agents.length > 0) {
                      logForDebugging(
                        `Loaded ${agents.length} agents from plugin ${plugin.name} custom path: ${agentPath}`,
                      )
                    }
                    return agents
                  } else if (stats.isFile() && agentPath.endsWith('.md')) {
                    // Load single agent file
                    const agent = await loadAgentFromFile(
                      agentPath,
                      plugin.name,
                      [],
                      plugin.source,
                      plugin.path,
                      plugin.manifest,
                      loadedPaths,
                    )
                    if (agent) {
                      logForDebugging(
                        `Loaded agent from plugin ${plugin.name} custom file: ${agentPath}`,
                      )
                      return [agent]
                    }
                  }
                  return []
                } catch (error) {
                  logForDebugging(
                    `Failed to load agents from plugin ${plugin.name} custom path ${agentPath}: ${error}`,
                    { level: 'error' },
                  )
                  return []
                }
              },
            ),
          )
          for (const agents of pathResults) {
            pluginAgents.push(...agents)
          }
        }
        return pluginAgents
      }),
    )

    const allAgents = perPluginAgents.flat()
    logForDebugging(`Total plugin agents loaded: ${allAgents.length}`)
    return allAgents
  },
)

export function clearPluginAgentCache(): void {
  loadPluginAgents.cache?.clear?.()
}

import memoize from 'lodash-es/memoize.js'
import { basename } from 'path'
import type { OutputStyleConfig } from './_deps.js'
import { getPluginErrorMessage } from './types.js'
import { logForDebugging } from './_deps.js'
import {
  coerceDescriptionToString,
  parseFrontmatter,
} from './_deps.js'
import { getFsImplementation, isDuplicatePath } from './_deps.js'
import { extractDescriptionFromMarkdown } from './_deps.js'
import { loadAllPluginsCacheOnly } from './pluginLoader.js'
import { walkPluginMarkdown } from './walkPluginMarkdown.js'

async function loadOutputStylesFromDirectory(
  outputStylesPath: string,
  pluginName: string,
  loadedPaths: Set<string>,
): Promise<OutputStyleConfig[]> {
  const styles: OutputStyleConfig[] = []
  await walkPluginMarkdown(
    outputStylesPath,
    async fullPath => {
      const style = await loadOutputStyleFromFile(
        fullPath,
        pluginName,
        loadedPaths,
      )
      if (style) styles.push(style)
    },
    { logLabel: 'output-styles' },
  )
  return styles
}

async function loadOutputStyleFromFile(
  filePath: string,
  pluginName: string,
  loadedPaths: Set<string>,
): Promise<OutputStyleConfig | null> {
  const fs = getFsImplementation()
  if (isDuplicatePath(filePath, loadedPaths)) {
    return null
  }
  try {
    const content = await fs.readFile(filePath, { encoding: 'utf-8' })
    const { frontmatter, content: markdownContent } = parseFrontmatter(
      content,
      filePath,
    )

    const fileName = basename(filePath, '.md')
    const baseStyleName = (frontmatter.name as string) || fileName
    // Namespace output styles with plugin name, consistent with commands and agents
    const name = `${pluginName}:${baseStyleName}`
    const description =
      (coerceDescriptionToString(frontmatter.description, name) as
        | string
        | null) ??
      extractDescriptionFromMarkdown(
        markdownContent,
        `Output style from ${pluginName} plugin`,
      )

    // Parse forceForPlugin flag (supports both boolean and string values)
    const forceRaw = frontmatter['force-for-plugin']
    const forceForPlugin =
      forceRaw === true || forceRaw === 'true'
        ? true
        : forceRaw === false || forceRaw === 'false'
          ? false
          : undefined

    return {
      name,
      description,
      prompt: markdownContent.trim(),
      source: 'plugin',
      forceForPlugin,
    }
  } catch (error) {
    logForDebugging(`Failed to load output style from ${filePath}: ${error}`, {
      level: 'error',
    })
    return null
  }
}

export const loadPluginOutputStyles = memoize(
  async (): Promise<OutputStyleConfig[]> => {
    // Only load output styles from enabled plugins
    const { enabled, errors } = await loadAllPluginsCacheOnly()
    const allStyles: OutputStyleConfig[] = []

    if (errors.length > 0) {
      logForDebugging(
        `Plugin loading errors: ${errors.map(e => getPluginErrorMessage(e)).join(', ')}`,
      )
    }

    for (const plugin of enabled) {
      // Track loaded file paths to prevent duplicates within this plugin
      const loadedPaths = new Set<string>()

      // Load output styles from default output-styles directory
      if (plugin.outputStylesPath) {
        try {
          const styles = await loadOutputStylesFromDirectory(
            plugin.outputStylesPath,
            plugin.name,
            loadedPaths,
          )
          allStyles.push(...styles)

          if (styles.length > 0) {
            logForDebugging(
              `Loaded ${styles.length} output styles from plugin ${plugin.name} default directory`,
            )
          }
        } catch (error) {
          logForDebugging(
            `Failed to load output styles from plugin ${plugin.name} default directory: ${error}`,
            { level: 'error' },
          )
        }
      }

      // Load output styles from additional paths specified in manifest
      if (plugin.outputStylesPaths) {
        for (const stylePath of plugin.outputStylesPaths) {
          try {
            const fs = getFsImplementation()
            const stats = (await fs.stat(stylePath)) as {
              mtime: Date
              isDirectory(): boolean
              isFile(): boolean
              size: number
            }

            if (stats.isDirectory()) {
              // Load all .md files from directory
              const styles = await loadOutputStylesFromDirectory(
                stylePath,
                plugin.name,
                loadedPaths,
              )
              allStyles.push(...styles)

              if (styles.length > 0) {
                logForDebugging(
                  `Loaded ${styles.length} output styles from plugin ${plugin.name} custom path: ${stylePath}`,
                )
              }
            } else if (stats.isFile() && stylePath.endsWith('.md')) {
              // Load single output style file
              const style = await loadOutputStyleFromFile(
                stylePath,
                plugin.name,
                loadedPaths,
              )
              if (style) {
                allStyles.push(style)
                logForDebugging(
                  `Loaded output style from plugin ${plugin.name} custom file: ${stylePath}`,
                )
              }
            }
          } catch (error) {
            logForDebugging(
              `Failed to load output styles from plugin ${plugin.name} custom path ${stylePath}: ${error}`,
              { level: 'error' },
            )
          }
        }
      }
    }

    logForDebugging(`Total plugin output styles loaded: ${allStyles.length}`)
    return allStyles
  },
)

export function clearPluginOutputStyleCache(): void {
  loadPluginOutputStyles.cache?.clear?.()
}

/**
 * Provides ripgrep glob exclusion patterns for orphaned plugin versions.
 *
 * When plugin versions are updated, old versions are marked with a
 * `.orphaned_at` file but kept on disk for 7 days (since concurrent
 * sessions might still reference them). During this window, Grep/Glob
 * could return files from orphaned versions, causing Claude to use
 * outdated plugin code.
 *
 * We find `.orphaned_at` markers via a single ripgrep call and generate
 * `--glob '!<dir>/**'` patterns for their parent directories. The cache
 * is warmed in main.tsx AFTER cleanupOrphanedPluginVersionsInBackground
 * settles disk state. Once populated, the exclusion list is frozen for
 * the session unless /reload-plugins is called; subsequent disk mutations
 * (autoupdate, concurrent sessions) don't affect it.
 */

import { dirname, isAbsolute, join, normalize, relative, sep } from 'path'
import { ripGrep } from './_deps.js'
import { getPluginsDirectory } from './pluginDirectories.js'

// Inlined from cacheUtils.ts to avoid a circular dep through commands.js.
const ORPHANED_AT_FILENAME = '.orphaned_at'

/** Session-scoped cache. Frozen once computed — only cleared by explicit /reload-plugins. */
let cachedExclusions: string[] | null = null

/**
 * Get ripgrep glob exclusion patterns for orphaned plugin versions.
 *
 * @param searchPath - When provided, exclusions are only returned if the
 *   search overlaps the plugin cache directory (avoids unnecessary --glob
 *   args for searches outside the cache).
 *
 * Warmed eagerly in main.tsx after orphan GC; the lazy-compute path here
 * is a fallback. Best-effort: returns empty array if anything goes wrong.
 */
export async function getGlobExclusionsForPluginCache(
  searchPath?: string,
): Promise<string[]> {
  const cachePath = normalize(join(getPluginsDirectory(), 'cache'))

  if (searchPath && !pathsOverlap(searchPath, cachePath)) {
    return []
  }

  if (cachedExclusions !== null) {
    return cachedExclusions
  }

  try {
    // Find all .orphaned_at files within the plugin cache directory.
    // --hidden: marker is a dotfile. --no-ignore: don't let a stray
    // .gitignore hide it. --max-depth 4: marker is always at
    // cache/<marketplace>/<plugin>/<version>/.orphaned_at — don't recurse
    // into plugin contents (node_modules, etc.). Never-aborts signal: no
    // caller signal to thread.
    const markers = await ripGrep(
      [
        '--files',
        '--hidden',
        '--no-ignore',
        '--max-depth',
        '4',
        '--glob',
        ORPHANED_AT_FILENAME,
      ],
      cachePath,
      new AbortController().signal,
    )

    const exclusions = markers.map((markerPath: string): string => {
      // ripgrep may return absolute or relative — normalize to relative.
      const versionDir = dirname(markerPath)
      const rel = isAbsolute(versionDir)
        ? relative(cachePath, versionDir)
        : versionDir
      // ripgrep glob patterns always use forward slashes, even on Windows
      const posixRelative = rel.replace(/\\/g, '/')
      return `!**/${posixRelative}/**`
    })
    cachedExclusions = exclusions
    return exclusions
  } catch {
    // Best-effort — don't break core search tools if ripgrep fails here
    cachedExclusions = []
    return cachedExclusions
  }
}

export function clearPluginCacheExclusions(): void {
  cachedExclusions = null
}

/**
 * One path is a prefix of the other. Special-cases root (normalize('/') + sep
 * = '//'). Case-insensitive on win32 since normalize() doesn't lowercase
 * drive letters and CLAUDE_CODE_PLUGIN_CACHE_DIR may disagree with resolved.
 */
function pathsOverlap(a: string, b: string): boolean {
  const na = normalizeForCompare(a)
  const nb = normalizeForCompare(b)
  return (
    na === nb ||
    na === sep ||
    nb === sep ||
    na.startsWith(nb + sep) ||
    nb.startsWith(na + sep)
  )
}

function normalizeForCompare(p: string): string {
  const n = normalize(p)
  return process.platform === 'win32' ? n.toLowerCase() : n
}

/**
 * Combines settings validation errors with MCP configuration errors.
 *
 * This module exists to break a circular dependency:
 *   settings.ts → mcp/config.ts → settings.ts
 *
 * V7 §8.6 / §11.1: config (Wave 1 leaf) cannot import from mcp-runtime
 * (Wave 5 integration). The MCP error retrieval is injected via the
 * ConfigHostBindings.getMcpErrorsByScope binding, which the app-host wires
 * to mcp-runtime at composition time.
 */

import { getConfigHostBindings } from '../host.js'
import { getSettingsWithErrors } from './settings.js'
import type { SettingsWithErrors } from './validation.js'

/**
 * Get merged settings with all validation errors, including MCP config errors.
 *
 * Use this instead of getSettingsWithErrors() when you need the full set of
 * errors (settings + MCP). The underlying getSettingsWithErrors() no longer
 * includes MCP errors to avoid the circular dependency.
 */
export function getSettingsWithAllErrors(): SettingsWithErrors {
  const result = getSettingsWithErrors()
  const getMcpErrors = getConfigHostBindings().getMcpErrorsByScope
  if (!getMcpErrors) {
    // Host binding not installed yet (early bootstrap or headless runs
    // that skip MCP). Return settings errors only.
    return result
  }
  // 'dynamic' scope does not have errors returned; it throws and is set on cli startup
  const scopes = ['user', 'project', 'local'] as const
  const mcpErrors = scopes.flatMap(scope =>
    getMcpErrors(scope).map(e => ({ ...e, file: e.file ?? '' })),
  )
  return {
    settings: result.settings,
    errors: [...result.errors, ...mcpErrors],
  }
}

/**
 * Settings Sync Service
 *
 * Syncs user settings and memory files across Claude Code environments.
 *
 * - Interactive CLI: Uploads local settings to remote (incremental, only changed entries)
 * - CCR: Downloads remote settings to local before plugin installation
 *
 * Backend API: anthropic/anthropic#218817
 */

import { feature } from 'bun:bundle'
import axios from 'axios'
import { mkdir, readFile, stat, writeFile } from 'fs/promises'
import pickBy from 'lodash-es/pickBy.js'
import { dirname } from 'path'
import { getConfigHostBindings, tryGetConfigHostBindings } from '../host.js'
import { getMemoryPath } from '../global/config.js'
import { markInternalWrite } from '../settings/internalWrites.js'
import { getSettingsFilePathForSource } from '../settings/settings.js'
import { resetSettingsCache } from '../settings/settingsCache.js'
import { getFeatureValue_CACHED_MAY_BE_STALE } from '../feature-flags.js'

// V7 §11.4 — inlined utilities (same as remote/index.ts)
function errorMessage(e: unknown): string { return e instanceof Error ? e.message : String(e) }
type AxiosErrorKind = 'network' | 'timeout' | 'http' | 'unknown'
function classifyAxiosError(e: unknown): { kind: AxiosErrorKind; status?: number; message: string } {
  const message = errorMessage(e)
  if (!e || typeof e !== 'object' || !('isAxiosError' in e)) return { kind: 'unknown', message }
  const ae = e as { code?: string; response?: { status?: number } }
  if (ae.code === 'ECONNABORTED') return { kind: 'timeout', message }
  if (!ae.response) return { kind: 'network', message }
  return { kind: 'http', status: ae.response.status, message }
}
function sleep(ms: number): Promise<void> { return new Promise(r => setTimeout(r, ms)) }
const BASE_RETRY_DELAY_MS = 500
function getRetryDelay(attempt: number, retryAfterHeader?: string | null, maxDelayMs = 32000): number {
  if (retryAfterHeader) { const s = parseInt(retryAfterHeader, 10); if (!isNaN(s)) return s * 1000 }
  const base = Math.min(BASE_RETRY_DELAY_MS * 2 ** (attempt - 1), maxDelayMs)
  return base + Math.random() * 0.25 * base
}
function getClaudeCodeUserAgent(): string { return `claude-code/${MACRO.VERSION}` }
import {
  type SettingsSyncFetchResult,
  type SettingsSyncUploadResult,
  SYNC_KEYS,
  UserSyncDataSchema,
} from './types.js'

const SETTINGS_SYNC_TIMEOUT_MS = 10000 // 10 seconds
const DEFAULT_MAX_RETRIES = 3
const MAX_FILE_SIZE_BYTES = 500 * 1024 // 500 KB per file (matches backend limit)

/**
 * Upload local settings to remote (interactive CLI only).
 * Called from main.tsx preAction.
 * Runs in background - caller should not await unless needed.
 */
export async function uploadUserSettingsInBackground(): Promise<void> {
  try {
    if (
      !feature('UPLOAD_USER_SETTINGS') ||
      !getFeatureValue_CACHED_MAY_BE_STALE(
        'tengu_enable_settings_sync_push',
        false,
      ) ||
      !getConfigHostBindings().isInteractive?.() ||
      !isUsingOAuth()
    ) {
      tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_upload_skipped')
      tryGetConfigHostBindings().logEvent?.('tengu_settings_sync_upload_skipped_ineligible', {})
      return
    }

    tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_upload_starting')
    const result = await fetchUserSettings()
    if (!result.success) {
      tryGetConfigHostBindings().logDiagnostics?.('warn', 'settings_sync_upload_fetch_failed')
      tryGetConfigHostBindings().logEvent?.('tengu_settings_sync_upload_fetch_failed', {})
      return
    }

    const projectId = (await getConfigHostBindings().getRepoRemoteHash?.()) ?? null
    const localEntries = await buildEntriesFromLocalFiles(projectId)
    const remoteEntries = result.isEmpty ? {} : result.data!.content.entries
    const changedEntries = pickBy(
      localEntries,
      (value, key) => remoteEntries[key] !== value,
    )

    const entryCount = Object.keys(changedEntries).length
    if (entryCount === 0) {
      tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_upload_no_changes')
      tryGetConfigHostBindings().logEvent?.('tengu_settings_sync_upload_skipped', {})
      return
    }

    const uploadResult = await uploadUserSettings(changedEntries)
    if (uploadResult.success) {
      tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_upload_success')
      tryGetConfigHostBindings().logEvent?.('tengu_settings_sync_upload_success', { entryCount })
    } else {
      tryGetConfigHostBindings().logDiagnostics?.('warn', 'settings_sync_upload_failed')
      tryGetConfigHostBindings().logEvent?.('tengu_settings_sync_upload_failed', { entryCount })
    }
  } catch {
    // Fail-open: log unexpected errors but don't block startup
    tryGetConfigHostBindings().logDiagnostics?.('error', 'settings_sync_unexpected_error')
  }
}

// Cached so the fire-and-forget at runHeadless entry and the await in
// installPluginsAndApplyMcpInBackground share one fetch.
let downloadPromise: Promise<boolean> | null = null

/** Test-only: clear the cached download promise between tests. */
export function _resetDownloadPromiseForTesting(): void {
  downloadPromise = null
}

/**
 * Download settings from remote for CCR mode.
 * Fired fire-and-forget at the top of print.ts runHeadless(); awaited in
 * installPluginsAndApplyMcpInBackground before plugin install. First call
 * starts the fetch; subsequent calls join it.
 * Returns true if settings were applied, false otherwise.
 */
export function downloadUserSettings(): Promise<boolean> {
  if (downloadPromise) {
    return downloadPromise
  }
  downloadPromise = doDownloadUserSettings()
  return downloadPromise
}

/**
 * Force a fresh download, bypassing the cached startup promise.
 * Called by /reload-plugins in CCR so mid-session settings changes
 * (enabledPlugins, extraKnownMarketplaces) pushed from the user's local
 * CLI are picked up before the plugin-cache sweep.
 *
 * No retries: user-initiated command, one attempt + fail-open. The user
 * can re-run /reload-plugins to retry. Startup path keeps DEFAULT_MAX_RETRIES.
 *
 * Caller is responsible for firing settingsChangeDetector.notifyChange
 * when this returns true — applyRemoteEntriesToLocal uses markInternalWrite
 * to suppress detection (correct for startup, but mid-session needs
 * applySettingsChange to run). Kept out of this module to avoid the
 * settingsSync → changeDetector cycle edge.
 */
export function redownloadUserSettings(): Promise<boolean> {
  downloadPromise = doDownloadUserSettings(0)
  return downloadPromise
}

async function doDownloadUserSettings(
  maxRetries = DEFAULT_MAX_RETRIES,
): Promise<boolean> {
  if (feature('DOWNLOAD_USER_SETTINGS')) {
    try {
      if (
        !getFeatureValue_CACHED_MAY_BE_STALE('tengu_strap_foyer', false) ||
        !isUsingOAuth()
      ) {
        tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_download_skipped')
        tryGetConfigHostBindings().logEvent?.('tengu_settings_sync_download_skipped', {})
        return false
      }

      tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_download_starting')
      const result = await fetchUserSettings(maxRetries)
      if (!result.success) {
        tryGetConfigHostBindings().logDiagnostics?.('warn', 'settings_sync_download_fetch_failed')
        tryGetConfigHostBindings().logEvent?.('tengu_settings_sync_download_fetch_failed', {})
        return false
      }

      if (result.isEmpty) {
        tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_download_empty')
        tryGetConfigHostBindings().logEvent?.('tengu_settings_sync_download_empty', {})
        return false
      }

      const entries = result.data!.content.entries
      const projectId = (await getConfigHostBindings().getRepoRemoteHash?.()) ?? null
      const entryCount = Object.keys(entries).length
      tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_download_applying', {
        entryCount,
      })
      await applyRemoteEntriesToLocal(entries, projectId)
      tryGetConfigHostBindings().logEvent?.('tengu_settings_sync_download_success', { entryCount })
      return true
    } catch {
      // Fail-open: log error but don't block CCR startup
      tryGetConfigHostBindings().logDiagnostics?.('error', 'settings_sync_download_error')
      tryGetConfigHostBindings().logEvent?.('tengu_settings_sync_download_error', {})
      return false
    }
  }
  return false
}

/**
 * Check if user is authenticated with first-party OAuth.
 * Required for settings sync in both CLI (upload) and CCR (download) modes.
 *
 * Only checks user:inference (not user:profile) — CCR's file-descriptor token
 * hardcodes scopes to ['user:inference'] only, so requiring profile would make
 * download a no-op there. Upload is independently guarded by getConfigHostBindings().isInteractive?.().
 */
// V7 §8.6 — auth/provider logic delegated to host binding
function isUsingOAuth(): boolean {
  const auth = getConfigHostBindings().getSettingsSyncAuth?.()
  return auth?.isEligible ?? false
}

function getSettingsSyncEndpoint(): string {
  const auth = getConfigHostBindings().getSettingsSyncAuth?.()
  return `${auth?.baseApiUrl ?? 'https://api.anthropic.com'}/api/claude_code/user_settings`
}

async function getSettingsSyncAuthHeaders(): Promise<{
  headers: Record<string, string>
  error?: string
}> {
  const auth = getConfigHostBindings().getSettingsSyncAuth?.()
  if (!auth) return { headers: {}, error: 'Auth binding not installed' }
  try {
    return { headers: await auth.getAuthHeaders() }
  } catch {
    return { headers: {}, error: 'Failed to get auth headers' }
  }
}

async function fetchUserSettingsOnce(): Promise<SettingsSyncFetchResult> {
  try {
    await getConfigHostBindings().getSettingsSyncAuth?.()?.refreshToken?.()

    const authHeaders = await getSettingsSyncAuthHeaders()
    if (authHeaders.error) {
      return {
        success: false,
        error: authHeaders.error,
        skipRetry: true,
      }
    }

    const headers: Record<string, string> = {
      ...authHeaders.headers,
      'User-Agent': getClaudeCodeUserAgent(),
    }

    const endpoint = getSettingsSyncEndpoint()
    const response = await axios.get(endpoint, {
      headers,
      timeout: SETTINGS_SYNC_TIMEOUT_MS,
      validateStatus: status => status === 200 || status === 404,
    })

    // 404 means no settings exist yet
    if (response.status === 404) {
      tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_fetch_empty')
      return {
        success: true,
        isEmpty: true,
      }
    }

    const parsed = UserSyncDataSchema().safeParse(response.data)
    if (!parsed.success) {
      tryGetConfigHostBindings().logDiagnostics?.('warn', 'settings_sync_fetch_invalid_format')
      return {
        success: false,
        error: 'Invalid settings sync response format',
      }
    }

    tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_fetch_success')
    return {
      success: true,
      data: parsed.data,
      isEmpty: false,
    }
  } catch (error) {
    const { kind, message } = classifyAxiosError(error)
    switch (kind) {
      case 'timeout':
        return { success: false, error: 'Settings sync request timeout' }
      case 'network':
        return { success: false, error: 'Cannot connect to server' }
      default:
        return { success: false, error: message }
    }
  }
}

async function fetchUserSettings(
  maxRetries = DEFAULT_MAX_RETRIES,
): Promise<SettingsSyncFetchResult> {
  let lastResult: SettingsSyncFetchResult | null = null

  for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
    lastResult = await fetchUserSettingsOnce()

    if (lastResult.success) {
      return lastResult
    }

    if (lastResult.skipRetry) {
      return lastResult
    }

    if (attempt > maxRetries) {
      return lastResult
    }

    const delayMs = getRetryDelay(attempt)
    tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_retry', {
      attempt,
      maxRetries,
      delayMs,
    })
    await sleep(delayMs)
  }

  return lastResult!
}

async function uploadUserSettings(
  entries: Record<string, string>,
): Promise<SettingsSyncUploadResult> {
  try {
    await getConfigHostBindings().getSettingsSyncAuth?.()?.refreshToken?.()

    const authHeaders = await getSettingsSyncAuthHeaders()
    if (authHeaders.error) {
      return {
        success: false,
        error: authHeaders.error,
      }
    }

    const headers: Record<string, string> = {
      ...authHeaders.headers,
      'User-Agent': getClaudeCodeUserAgent(),
      'Content-Type': 'application/json',
    }

    const endpoint = getSettingsSyncEndpoint()
    const response = await axios.put(
      endpoint,
      { entries },
      {
        headers,
        timeout: SETTINGS_SYNC_TIMEOUT_MS,
      },
    )

    tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_uploaded', {
      entryCount: Object.keys(entries).length,
    })
    return {
      success: true,
      checksum: response.data?.checksum,
      lastModified: response.data?.lastModified,
    }
  } catch (error) {
    tryGetConfigHostBindings().logDiagnostics?.('warn', 'settings_sync_upload_error')
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error',
    }
  }
}

/**
 * Try to read a file for sync, with size limit and error handling.
 * Returns null if file doesn't exist, is empty, or exceeds size limit.
 */
async function tryReadFileForSync(filePath: string): Promise<string | null> {
  try {
    const stats = await stat(filePath)
    if (stats.size > MAX_FILE_SIZE_BYTES) {
      tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_file_too_large')
      return null
    }

    const content = await readFile(filePath, 'utf8')
    // Check for empty/whitespace-only without allocating a trimmed copy
    if (!content || /^\s*$/.test(content)) {
      return null
    }

    return content
  } catch {
    return null
  }
}

async function buildEntriesFromLocalFiles(
  projectId: string | null,
): Promise<Record<string, string>> {
  const entries: Record<string, string> = {}

  // Global user settings
  const userSettingsPath = getSettingsFilePathForSource('userSettings')
  if (userSettingsPath) {
    const content = await tryReadFileForSync(userSettingsPath)
    if (content) {
      entries[SYNC_KEYS.USER_SETTINGS] = content
    }
  }

  // Global user memory
  const userMemoryPath = getMemoryPath('User')
  const userMemoryContent = await tryReadFileForSync(userMemoryPath)
  if (userMemoryContent) {
    entries[SYNC_KEYS.USER_MEMORY] = userMemoryContent
  }

  // Project-specific files (only if we have a project ID from git remote)
  if (projectId) {
    // Project local settings
    const localSettingsPath = getSettingsFilePathForSource('localSettings')
    if (localSettingsPath) {
      const content = await tryReadFileForSync(localSettingsPath)
      if (content) {
        entries[SYNC_KEYS.projectSettings(projectId)] = content
      }
    }

    // Project local memory
    const localMemoryPath = getMemoryPath('Local')
    const localMemoryContent = await tryReadFileForSync(localMemoryPath)
    if (localMemoryContent) {
      entries[SYNC_KEYS.projectMemory(projectId)] = localMemoryContent
    }
  }

  return entries
}

async function writeFileForSync(
  filePath: string,
  content: string,
): Promise<boolean> {
  try {
    const parentDir = dirname(filePath)
    if (parentDir) {
      await mkdir(parentDir, { recursive: true })
    }

    await writeFile(filePath, content, 'utf8')
    tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_file_written')
    return true
  } catch {
    tryGetConfigHostBindings().logDiagnostics?.('warn', 'settings_sync_file_write_failed')
    return false
  }
}

/**
 * Apply remote entries to local files (CCR pull pattern).
 * Only writes files that match expected keys.
 *
 * After writing, invalidates relevant caches:
 * - resetSettingsCache() for settings files
 * - getConfigHostBindings().clearMemoryFileCaches?.() for memory files (CLAUDE.md)
 */
async function applyRemoteEntriesToLocal(
  entries: Record<string, string>,
  projectId: string | null,
): Promise<void> {
  let appliedCount = 0
  let settingsWritten = false
  let memoryWritten = false

  // Helper to check size limit (defense-in-depth, matches backend limit)
  const exceedsSizeLimit = (content: string, _path: string): boolean => {
    const sizeBytes = Buffer.byteLength(content, 'utf8')
    if (sizeBytes > MAX_FILE_SIZE_BYTES) {
      tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_file_too_large', {
        sizeBytes,
        maxBytes: MAX_FILE_SIZE_BYTES,
      })
      return true
    }
    return false
  }

  // Apply global user settings
  const userSettingsContent = entries[SYNC_KEYS.USER_SETTINGS]
  if (userSettingsContent) {
    const userSettingsPath = getSettingsFilePathForSource('userSettings')
    if (
      userSettingsPath &&
      !exceedsSizeLimit(userSettingsContent, userSettingsPath)
    ) {
      // Mark as internal write to prevent spurious change detection
      markInternalWrite(userSettingsPath)
      if (await writeFileForSync(userSettingsPath, userSettingsContent)) {
        appliedCount++
        settingsWritten = true
      }
    }
  }

  // Apply global user memory
  const userMemoryContent = entries[SYNC_KEYS.USER_MEMORY]
  if (userMemoryContent) {
    const userMemoryPath = getMemoryPath('User')
    if (!exceedsSizeLimit(userMemoryContent, userMemoryPath)) {
      if (await writeFileForSync(userMemoryPath, userMemoryContent)) {
        appliedCount++
        memoryWritten = true
      }
    }
  }

  // Apply project-specific files (only if project ID matches)
  if (projectId) {
    const projectSettingsKey = SYNC_KEYS.projectSettings(projectId)
    const projectSettingsContent = entries[projectSettingsKey]
    if (projectSettingsContent) {
      const localSettingsPath = getSettingsFilePathForSource('localSettings')
      if (
        localSettingsPath &&
        !exceedsSizeLimit(projectSettingsContent, localSettingsPath)
      ) {
        // Mark as internal write to prevent spurious change detection
        markInternalWrite(localSettingsPath)
        if (await writeFileForSync(localSettingsPath, projectSettingsContent)) {
          appliedCount++
          settingsWritten = true
        }
      }
    }

    const projectMemoryKey = SYNC_KEYS.projectMemory(projectId)
    const projectMemoryContent = entries[projectMemoryKey]
    if (projectMemoryContent) {
      const localMemoryPath = getMemoryPath('Local')
      if (!exceedsSizeLimit(projectMemoryContent, localMemoryPath)) {
        if (await writeFileForSync(localMemoryPath, projectMemoryContent)) {
          appliedCount++
          memoryWritten = true
        }
      }
    }
  }

  // Invalidate caches so subsequent reads pick up new content
  if (settingsWritten) {
    resetSettingsCache()
  }
  if (memoryWritten) {
    getConfigHostBindings().clearMemoryFileCaches?.()
  }

  tryGetConfigHostBindings().logDiagnostics?.('info', 'settings_sync_applied', {
    appliedCount,
  })
}

import { afterEach, beforeEach, describe, expect, test } from 'bun:test'
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'
import { drainSpool, ingestEnvelope, writeSpoolEnvelope } from '../dispatchSpool.js'

const SPOOL = join(homedir(), '.claude', 'daemon', 'dispatch')
const REJECTED = join(SPOOL, 'rejected')

function clearSpool(): void {
  try {
    rmSync(SPOOL, { recursive: true, force: true })
  } catch {}
  mkdirSync(SPOOL, { recursive: true, mode: 0o700 })
}

beforeEach(clearSpool)
afterEach(clearSpool)

describe('writeSpoolEnvelope', () => {
  test('atomic write + valid filename', () => {
    const path = writeSpoolEnvelope({
      createdAt: Date.now(),
      op: 'dispatch',
      d: { short: 'abc', cwd: '/tmp' },
    })
    expect(existsSync(path)).toBe(true)
    expect(path.endsWith('.json')).toBe(true)
    const parsed = JSON.parse(readFileSync(path, 'utf8'))
    expect(parsed.op).toBe('dispatch')
    expect(parsed.d.short).toBe('abc')
  })
})

describe('ingestEnvelope', () => {
  test('valid envelope is delivered + file consumed', async () => {
    const path = writeSpoolEnvelope({ createdAt: Date.now(), op: 'spawn', d: { short: 'x' } })
    let delivered: unknown
    const reason = await ingestEnvelope(path, env => { delivered = env })
    expect(reason).toBe(null)
    expect(existsSync(path)).toBe(false)
    expect((delivered as { op: string }).op).toBe('spawn')
  })

  test('stale envelope (>24h) is rejected', async () => {
    const path = writeSpoolEnvelope({ createdAt: Date.now() - 86_400_001, op: 'spawn', d: {} })
    const reason = await ingestEnvelope(path, () => {})
    expect(reason).toBe('stale')
    expect(existsSync(path)).toBe(false)
  })

  test('bad json is rejected', async () => {
    const path = join(SPOOL, 'bad.json')
    writeFileSync(path, '{not json')
    const reason = await ingestEnvelope(path, () => {})
    expect(reason).toBe('bad-json')
  })

  test('schema-invalid (missing op) is rejected', async () => {
    const path = join(SPOOL, 'noop.json')
    writeFileSync(path, JSON.stringify({ createdAt: Date.now(), d: {} }))
    const reason = await ingestEnvelope(path, () => {})
    expect(reason).toBe('schema')
  })

  test('oversized payload (>256 KiB) is rejected', async () => {
    const path = join(SPOOL, 'big.json')
    const big = 'x'.repeat(300_000)
    writeFileSync(path, JSON.stringify({ createdAt: Date.now(), op: 'spawn', d: { big } }))
    const reason = await ingestEnvelope(path, () => {})
    expect(reason).toBe('oversized')
  })

  test('missing file returns null (race-safe)', async () => {
    const reason = await ingestEnvelope(join(SPOOL, 'gone.json'), () => {})
    expect(reason).toBe(null)
  })

  test('rejected files moved to rejected/ subdir', async () => {
    const path = join(SPOOL, 'badjson.json')
    writeFileSync(path, '{not json')
    await ingestEnvelope(path, () => {})
    expect(existsSync(REJECTED)).toBe(true)
  })

  test('deliver-throws marks deliver-failed + rejects', async () => {
    const path = writeSpoolEnvelope({ createdAt: Date.now(), op: 'spawn', d: {} })
    const reason = await ingestEnvelope(path, () => { throw new Error('boom') })
    expect(reason).toBe('deliver-failed')
  })
})

describe('drainSpool', () => {
  test('processes all pending envelopes on boot', async () => {
    writeSpoolEnvelope({ createdAt: Date.now(), op: 'spawn', d: { id: 1 } })
    writeSpoolEnvelope({ createdAt: Date.now(), op: 'spawn', d: { id: 2 } })
    writeSpoolEnvelope({ createdAt: Date.now(), op: 'spawn', d: { id: 3 } })
    const ids: unknown[] = []
    await drainSpool(env => {
      ids.push((env.d as { id: number }).id)
    })
    expect(ids.sort()).toEqual([1, 2, 3])
  })

  test('skips .tmp files', async () => {
    writeFileSync(join(SPOOL, '12345.tmp'), '{}')
    writeSpoolEnvelope({ createdAt: Date.now(), op: 'spawn', d: {} })
    let count = 0
    await drainSpool(() => {
      count++
    })
    expect(count).toBe(1)
  })

  test('empty dir is a no-op', async () => {
    let count = 0
    await drainSpool(() => {
      count++
    })
    expect(count).toBe(0)
  })

  test('handles missing dir', async () => {
    rmSync(SPOOL, { recursive: true, force: true })
    let count = 0
    await drainSpool(() => {
      count++
    })
    expect(count).toBe(0)
  })
})

import { describe, expect, test } from 'bun:test'
import { normalizeControlMessageKeys } from '../controlMessageCompat.js'

/**
 * `normalizeControlMessageKeys` muta el objeto reemplazando `requestId` por
 * `request_id`; el tipo inferido del literal no lo refleja, así que se
 * declara explícitamente para que `toEqual` acepte ambas grafías.
 */
type RequestIdKeys = { requestId?: string; request_id?: string }

describe('normalizeControlMessageKeys — non-object inputs', () => {
  test('null passes through unchanged', () => {
    expect(normalizeControlMessageKeys(null)).toBe(null)
  })
  test('undefined passes through unchanged', () => {
    expect(normalizeControlMessageKeys(undefined)).toBe(undefined)
  })
  test('numbers pass through unchanged', () => {
    expect(normalizeControlMessageKeys(42)).toBe(42)
  })
  test('strings pass through unchanged', () => {
    expect(normalizeControlMessageKeys('hello')).toBe('hello')
  })
  test('booleans pass through unchanged', () => {
    expect(normalizeControlMessageKeys(true)).toBe(true)
  })
})

describe('normalizeControlMessageKeys — top-level requestId', () => {
  test('renames camelCase requestId → snake_case request_id', () => {
    const input: RequestIdKeys = { requestId: 'abc123' }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({ request_id: 'abc123' })
  })

  test('mutates in place (returns same reference)', () => {
    // Contract: function mutates rather than clone — declared in JSDoc.
    // Callers may rely on mutation semantics for performance.
    const input = { requestId: 'x' }
    const result = normalizeControlMessageKeys(input)
    expect(result).toBe(input)
  })

  test('does NOT touch existing request_id when both keys present', () => {
    // Contract: snake_case wins. The camelCase key is dropped, but
    // the existing snake_case value is preserved as-is.
    const input = { request_id: 'snake-wins', requestId: 'camel-loses' }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({ request_id: 'snake-wins', requestId: 'camel-loses' })
  })

  test('only renames when request_id is absent', () => {
    const input = { request_id: 'preserve-me' }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({ request_id: 'preserve-me' })
  })

  test('does nothing for an empty object', () => {
    const input = {}
    normalizeControlMessageKeys(input)
    expect(input).toEqual({})
  })

  test('preserves other keys', () => {
    const input: RequestIdKeys & { method: string; params: { a: number } } = { requestId: 'r1', method: 'subscribe', params: { a: 1 } }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({
      request_id: 'r1',
      method: 'subscribe',
      params: { a: 1 },
    })
  })
})

describe('normalizeControlMessageKeys — nested response.requestId', () => {
  test('renames response.requestId → response.request_id', () => {
    const input: { type: string; response: RequestIdKeys } = { type: 'control_response', response: { requestId: 'nested-abc' } }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({
      type: 'control_response',
      response: { request_id: 'nested-abc' },
    })
  })

  test('preserves other response fields', () => {
    const input: { response: RequestIdKeys & { subtype: string; data: { x: number } } } = {
      response: { requestId: 'r1', subtype: 'success', data: { x: 42 } },
    }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({
      response: { request_id: 'r1', subtype: 'success', data: { x: 42 } },
    })
  })

  test('handles BOTH top-level and nested rename in a single call', () => {
    const input: RequestIdKeys & { response: RequestIdKeys } = {
      requestId: 'outer',
      response: { requestId: 'inner' },
    }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({
      request_id: 'outer',
      response: { request_id: 'inner' },
    })
  })

  test('snake_case in nested response wins over camelCase', () => {
    const input = {
      response: { request_id: 'snake', requestId: 'camel' },
    }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({
      response: { request_id: 'snake', requestId: 'camel' },
    })
  })

  test('null response is left alone', () => {
    const input = { response: null }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({ response: null })
  })

  test('non-object response (string) is left alone', () => {
    const input = { response: 'literal-string' }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({ response: 'literal-string' })
  })

  test('does not recurse into deeply-nested objects (only one level)', () => {
    // Contract: only top-level + response.X are normalized. A
    // hypothetical response.payload.requestId is NOT touched. This
    // documents the depth-limit contract.
    const input = {
      response: {
        payload: { requestId: 'deeply-nested' },
      },
    }
    normalizeControlMessageKeys(input)
    expect(input).toEqual({
      response: { payload: { requestId: 'deeply-nested' } },
    })
  })
})

describe('normalizeControlMessageKeys — return value', () => {
  test('returns the same object reference on success', () => {
    const input = { requestId: 'x' }
    expect(normalizeControlMessageKeys(input)).toBe(input)
  })
  test('returns null when given null (no clone)', () => {
    expect(normalizeControlMessageKeys(null)).toBe(null)
  })
})

import { fileURLToPath } from 'url'
import { Diagnostic, type PublishDiagnosticsParams } from 'vscode-languageserver-protocol'
import { logForDebugging } from '@thyrox/local-observability/debug.js'
import { toError } from '@thyrox/local-observability/errorHelpers.js'
import { logError } from '@thyrox/local-observability/logging'
import { jsonStringify } from '@thyrox/local-observability/slowOperations.js'
import type { DiagnosticFile } from '@thyrox/tool-registry/diagnosticTracking.js'
import { registerPendingLSPDiagnostic } from './LSPDiagnosticRegistry.js'
import type { LSPServerManager } from './LSPServerManager.js'

/**
 * Map LSP severity to Claude diagnostic severity
 *
 * Maps LSP severity numbers to Claude diagnostic severity strings.
 * Accepts numeric severity values (1=Error, 2=Warning, 3=Information, 4=Hint)
 * or undefined, defaulting to 'Error' for invalid/missing values.
 */
function mapLSPSeverity(
  lspSeverity: number | undefined,
): 'Error' | 'Warning' | 'Info' | 'Hint' {
  // LSP DiagnosticSeverity enum:
  // 1 = Error, 2 = Warning, 3 = Information, 4 = Hint
  switch (lspSeverity) {
    case 1:
      return 'Error'
    case 2:
      return 'Warning'
    case 3:
      return 'Info'
    case 4:
      return 'Hint'
    default:
      return 'Error'
  }
}

/**
 * Convert LSP diagnostics to Claude diagnostic format
 *
 * Converts LSP PublishDiagnosticsParams to DiagnosticFile[] format
 * used by Claude's attachment system.
 */
export function formatDiagnosticsForAttachment(
  params: PublishDiagnosticsParams,
): DiagnosticFile[] {
  // Parse URI (may be file:// or plain path) and normalize to file system path
  let uri: string
  try {
    // Handle both file:// URIs and plain paths
    uri = params.uri.startsWith('file://')
      ? fileURLToPath(params.uri)
      : params.uri
  } catch (error) {
    const err = toError(error)
    logError(err)
    logForDebugging(
      `Failed to convert URI to file path: ${params.uri}. Error: ${err.message}. Using original URI as fallback.`,
    )
    // Gracefully fallback to original URI - LSP servers may send malformed URIs
    uri = params.uri
  }

  const diagnostics = params.diagnostics.map((diag: Diagnostic) => ({
      message: Diagnostic.getMessageString(diag),
      severity: mapLSPSeverity(diag.severity),
      range: {
        start: {
          line: diag.range.start.line,
          character: diag.range.start.character,
        },
        end: {
          line: diag.range.end.line,
          character: diag.range.end.character,
        },
      },
      source: diag.source,
      code:
        diag.code !== undefined && diag.code !== null
          ? String(diag.code)
          : undefined,
    }),
  )

  return [
    {
      uri,
      diagnostics,
    },
  ]
}

/**
 * Handler registration result with tracking data
 */
export type HandlerRegistrationResult = {
  /** Total number of servers */
  totalServers: number
  /** Number of successful registrations */
  successCount: number
  /** Registration errors per server */
  registrationErrors: Array<{ serverName: string; error: string }>
  /** Runtime failure tracking (shared across all handler invocations) */
  diagnosticFailures: Map<string, { count: number; lastError: string }>
}

/**
 * Register LSP notification handlers on all servers
 *
 * Sets up handlers to listen for textDocument/publishDiagnostics notifications
 * from all LSP servers and routes them to Claude's diagnostic system.
 * Uses public getAllServers() API for clean access to server instances.
 *
 * @returns Tracking data for registration status and runtime failures
 */
export function registerLSPNotificationHandlers(
  manager: LSPServerManager,
): HandlerRegistrationResult {
  // Register handlers on all configured servers to capture diagnostics from any language
  const servers = manager.getAllServers()

  // Track partial failures - allow successful server registrations even if some fail
  const registrationErrors: Array<{ serverName: string; error: string }> = []
  let successCount = 0

  // Track consecutive failures per server to warn users after 3+ failures
  const diagnosticFailures: Map<string, { count: number; lastError: string }> =
    new Map()

  for (const [serverName, serverInstance] of servers.entries()) {
    try {
      // Validate server instance has onNotification method
      if (
        !serverInstance ||
        typeof serverInstance.onNotification !== 'function'
      ) {
        const errorMsg = !serverInstance
          ? 'Server instance is null/undefined'
          : 'Server instance has no onNotification method'

        registrationErrors.push({ serverName, error: errorMsg })

        const err = new Error(`${errorMsg} for ${serverName}`)
        logError(err)
        logForDebugging(
          `Skipping handler registration for ${serverName}: ${errorMsg}`,
        )
        continue // Skip this server but track the failure
      }

      // Errors are isolated to avoid breaking other servers
      serverInstance.onNotification(
        'textDocument/publishDiagnostics',
        (params: unknown) => {
          logForDebugging(
            `[PASSIVE DIAGNOSTICS] Handler invoked for ${serverName}! Params type: ${typeof params}`,
          )
          try {
            // Validate params structure before casting
            if (
              !params ||
              typeof params !== 'object' ||
              !('uri' in params) ||
              !('diagnostics' in params)
            ) {
              const err = new Error(
                `LSP server ${serverName} sent invalid diagnostic params (missing uri or diagnostics)`,
              )
              logError(err)
              logForDebugging(
                `Invalid diagnostic params from ${serverName}: ${jsonStringify(params)}`,
              )
              return
            }

            const diagnosticParams = params as PublishDiagnosticsParams
            logForDebugging(
              `Received diagnostics from ${serverName}: ${diagnosticParams.diagnostics.length} diagnostic(s) for ${diagnosticParams.uri}`,
            )

            // Convert LSP diagnostics to Claude format (can throw on invalid URIs)
            const diagnosticFiles =
              formatDiagnosticsForAttachment(diagnosticParams)

            // Only send notification if there are diagnostics
            const firstFile = diagnosticFiles[0]
            if (
              !firstFile ||
              diagnosticFiles.length === 0 ||
              firstFile.diagnostics.length === 0
            ) {
              logForDebugging(
                `Skipping empty diagnostics from ${serverName} for ${diagnosticParams.uri}`,
              )
              return
            }

            // Register diagnostics for async delivery via attachment system
            // Follows same pattern as AsyncHookRegistry for consistent async attachment delivery
            try {
              registerPendingLSPDiagnostic({
                serverName,
                files: diagnosticFiles,
              })

              logForDebugging(
                `LSP Diagnostics: Registered ${diagnosticFiles.length} diagnostic file(s) from ${serverName} for async delivery`,
              )

              // Success - reset failure counter for this server
              diagnosticFailures.delete(serverName)
            } catch (error) {
              const err = toError(error)
              logError(err)
              logForDebugging(
                `Error registering LSP diagnostics from ${serverName}: ` +
                  `URI: ${diagnosticParams.uri}, ` +
                  `Diagnostic count: ${firstFile.diagnostics.length}, ` +
                  `Error: ${err.message}`,
              )

              // Track consecutive failures and warn after 3+
              const failures = diagnosticFailures.get(serverName) || {
                count: 0,
                lastError: '',
              }
              failures.count++
              failures.lastError = err.message
              diagnosticFailures.set(serverName, failures)

              if (failures.count >= 3) {
                logForDebugging(
                  `WARNING: LSP diagnostic handler for ${serverName} has failed ${failures.count} times consecutively. ` +
                    `Last error: ${failures.lastError}. ` +
                    `This may indicate a problem with the LSP server or diagnostic processing. ` +
                    `Check logs for details.`,
                )
              }
            }
          } catch (error) {
            // Catch any unexpected errors from the entire handler to prevent breaking the notification loop
            const err = toError(error)
            logError(err)
            logForDebugging(
              `Unexpected error processing diagnostics from ${serverName}: ${err.message}`,
            )

            // Track consecutive failures and warn after 3+
            const failures = diagnosticFailures.get(serverName) || {
              count: 0,
              lastError: '',
            }
            failures.count++
            failures.lastError = err.message
            diagnosticFailures.set(serverName, failures)

            if (failures.count >= 3) {
              logForDebugging(
                `WARNING: LSP diagnostic handler for ${serverName} has failed ${failures.count} times consecutively. ` +
                  `Last error: ${failures.lastError}. ` +
                  `This may indicate a problem with the LSP server or diagnostic processing. ` +
                  `Check logs for details.`,
              )
            }

            // Don't re-throw - isolate errors to this server only
          }
        },
      )

      logForDebugging(`Registered diagnostics handler for ${serverName}`)
      successCount++
    } catch (error) {
      const err = toError(error)

      registrationErrors.push({
        serverName,
        error: err.message,
      })

      logError(err)
      logForDebugging(
        `Failed to register diagnostics handler for ${serverName}: ` +
          `Error: ${err.message}`,
      )
    }
  }

  // Report overall registration status
  const totalServers = servers.size
  if (registrationErrors.length > 0) {
    const failedServers = registrationErrors
      .map(e => `${e.serverName} (${e.error})`)
      .join(', ')
    // Log aggregate failures for tracking
    logError(
      new Error(
        `Failed to register diagnostics for ${registrationErrors.length} LSP server(s): ${failedServers}`,
      ),
    )
    logForDebugging(
      `LSP notification handler registration: ${successCount}/${totalServers} succeeded. ` +
        `Failed servers: ${failedServers}. ` +
        `Diagnostics from failed servers will not be delivered.`,
    )
  } else {
    logForDebugging(
      `LSP notification handlers registered successfully for all ${totalServers} server(s)`,
    )
  }

  // Return tracking data for monitoring and testing
  return {
    totalServers,
    successCount,
    registrationErrors,
    diagnosticFailures,
  }
}

/**
 * Puerto de `ccnmt: packages/local-observability/src/aggregates/stats.ts`
 * (1061 líneas fuente). Agrega estadísticas de uso de Claude Code a
 * través de todas las sesiones — la más citada de las 6 subpaths de
 * `aggregates/` en el censo de futuros consumidores (`stats.js`: 1 línea
 * directa, pero `DailyActivity`/`SessionStats` los consumen `heatmap.ts`
 * y `statsCache.ts` de este mismo paquete).
 *
 * NO PORTADO: la rama `feature('SHOT_STATS')` (5 sitios: extracción del
 * conteo de shots desde atribución de PR, `shotDistribution`,
 * `oneShotRate`) — macro de `bun:bundle` ausente en este árbol, resuelve
 * siempre `false` fuera de un build ant. Los campos opcionales
 * `shotDistribution`/`oneShotRate` de `ClaudeCodeStats` SÍ se conservan
 * en el tipo (contrato público); el código que los puebla nunca se
 * alcanza.
 *
 * Sustituidos localmente (`internal/pendingCrossPackageDeps.ts`):
 * - `ModelUsage` — tipo estructural estrecho, `headless-sdk` no existe
 *   en este árbol.
 * - `Entry`/`TranscriptMessage` — tipo estructural estrecho,
 *   `@thyrox/agent` no exporta `./logsTypes`.
 * - `getFsImplementation` — storage/fsOperations, subpath no exportado.
 * - `readJSONLFile` — storage/json.js, subpath no exportado; sustituto
 *   más simple (sin camino rápido nativo de Bun ni recuperación de línea
 *   corrupta parcial — divergencia declarada en el propio sustituto).
 * - `SYNTHETIC_MODEL` — agent/messagesConstants.js, no exportado.
 * - `getProjectsDir`/`isTranscriptMessage` — storage/sessionStorage.js
 *   / sessionStoragePredicates.js, no exportados.
 *
 * NO IMPORTADO (a propósito): `SHELL_TOOL_NAMES` —
 * `shell/legacy/shellToolUtils.js`, no exportado por `@thyrox/shell`.
 * Su único call site en la fuente es `extractShotCountFromMessages`,
 * que vive enteramente detrás de `feature('SHOT_STATS')` — ver más abajo.
 *
 * HALLAZGO DE LA FUENTE (no de este porte, documentado verbatim): el
 * comentario de `TRANSCRIPT_MESSAGE_TYPES` dice "must match
 * isTranscriptMessage()", pero el Set incluye `'progress'` mientras
 * `isTranscriptMessage` real (`sessionStoragePredicates.ts:21-27`)
 * excluye explícitamente `'progress'`. Se porta el Set EXACTO de la
 * fuente (fiel al porte), citando la discrepancia — ver
 * `hallazgo-H-DOCS-1150-el-set-de-tipos-de-transcript-no-seguio-a-su-propio-comentario.rst`.
 */

import { open } from 'fs/promises'
import { basename, join, sep } from 'path'
import { errorMessage, isENOENT } from '../errorHelpers.js'
import { logForDebugging } from '../debug.js'
import {
  type Entry,
  getFsImplementation,
  getProjectsDir,
  isTranscriptMessage,
  type ModelUsage,
  readJSONLFile,
  type SpeculationAcceptEntry,
  SYNTHETIC_MODEL,
  type TranscriptMessage,
} from '../internal/pendingCrossPackageDeps.js'
import { jsonParse } from '../slowOperations.js'
import {
  getTodayDateString,
  getYesterdayDateString,
  isDateBefore,
  loadStatsCache,
  mergeCacheWithNewStats,
  type PersistedStatsCache,
  saveStatsCache,
  toDateString,
  withStatsCacheLock,
} from './statsCache.js'

export type DailyActivity = {
  date: string // formato YYYY-MM-DD
  messageCount: number
  sessionCount: number
  toolCallCount: number
}

export type DailyModelTokens = {
  date: string // formato YYYY-MM-DD
  tokensByModel: { [modelName: string]: number } // tokens totales (input + output) por modelo
}

export type StreakInfo = {
  currentStreak: number
  longestStreak: number
  currentStreakStart: string | null
  longestStreakStart: string | null
  longestStreakEnd: string | null
}

export type SessionStats = {
  sessionId: string
  duration: number // en milisegundos
  messageCount: number
  timestamp: string
}

export type ClaudeCodeStats = {
  // Resumen de actividad
  totalSessions: number
  totalMessages: number
  totalDays: number
  activeDays: number

  // Streaks
  streaks: StreakInfo

  // Actividad diaria para el heatmap
  dailyActivity: DailyActivity[]

  // Uso diario de tokens por modelo, para gráficos
  dailyModelTokens: DailyModelTokens[]

  // Info de sesión
  longestSession: SessionStats | null

  // Uso de modelo agregado
  modelUsage: { [modelName: string]: ModelUsage }

  // Stats de tiempo
  firstSessionDate: string | null
  lastSessionDate: string | null
  peakActivityDay: string | null
  peakActivityHour: number | null

  // Tiempo de especulación ahorrado
  totalSpeculationTimeSavedMs: number

  // Stats de shots (sólo-ant, gateado por el feature flag SHOT_STATS —
  // ver docstring del módulo: el código que los puebla es inalcanzable
  // en este árbol; los campos se conservan en el contrato público)
  shotDistribution?: { [shotCount: number]: number }
  oneShotRate?: number
}

/**
 * Resultado de procesar archivos de sesión — stats intermedias que se
 * pueden mezclar.
 */
type ProcessedStats = {
  dailyActivity: DailyActivity[]
  dailyModelTokens: DailyModelTokens[]
  modelUsage: { [modelName: string]: ModelUsage }
  sessionStats: SessionStats[]
  hourCounts: { [hour: number]: number }
  totalMessages: number
  totalSpeculationTimeSavedMs: number
  shotDistribution?: { [shotCount: number]: number }
}

/** Opciones para procesar archivos de sesión. */
type ProcessOptions = {
  // Sólo incluye datos de fechas >= esta fecha (formato YYYY-MM-DD).
  fromDate?: string
  // Sólo incluye datos de fechas <= esta fecha (formato YYYY-MM-DD).
  toDate?: string
}

/**
 * Procesa archivos de sesión y extrae stats.
 * Puede filtrar por rango de fechas.
 */
async function processSessionFiles(
  sessionFiles: string[],
  options: ProcessOptions = {},
): Promise<ProcessedStats> {
  const { fromDate, toDate } = options
  const fs = getFsImplementation()

  const dailyActivityMap = new Map<string, DailyActivity>()
  const dailyModelTokensMap = new Map<string, { [modelName: string]: number }>()
  const sessions: SessionStats[] = []
  const hourCounts = new Map<number, number>()
  let totalMessages = 0
  let totalSpeculationTimeSavedMs = 0
  const modelUsageAgg: { [modelName: string]: ModelUsage } = {}

  // Procesa archivos de sesión en lotes paralelos para mejor rendimiento.
  const BATCH_SIZE = 20
  for (let i = 0; i < sessionFiles.length; i += BATCH_SIZE) {
    const batch = sessionFiles.slice(i, i + BATCH_SIZE)
    const results = await Promise.all(
      batch.map(async sessionFile => {
        try {
          // Si hay un filtro fromDate, se saltan archivos que no han
          // sido modificados desde entonces.
          if (fromDate) {
            let fileSize = 0
            try {
              const fileStat = await fs.stat(sessionFile)
              const fileModifiedDate = toDateString(fileStat.mtime)
              if (isDateBefore(fileModifiedDate, fromDate)) {
                return {
                  sessionFile,
                  entries: null,
                  error: null,
                  skipped: true,
                }
              }
              fileSize = fileStat.size
            } catch {
              // Si no se puede hacer stat, se intenta leer igual.
            }
            // Para archivos grandes, se espía la fecha de inicio de
            // sesión antes de leer todo. Sesiones que pasan el filtro de
            // mtime pero empezaron antes de fromDate se saltan (p. ej.
            // una sesión de hace un mes retomada hoy tiene mtime nuevo
            // pero fecha de inicio vieja).
            if (fileSize > 65536) {
              const startDate = await readSessionStartDate(sessionFile)
              if (startDate && isDateBefore(startDate, fromDate)) {
                return {
                  sessionFile,
                  entries: null,
                  error: null,
                  skipped: true,
                }
              }
            }
          }
          const entries = await readJSONLFile<Entry>(sessionFile)
          return { sessionFile, entries, error: null, skipped: false }
        } catch (error) {
          return { sessionFile, entries: null, error, skipped: false }
        }
      }),
    )

    for (const { sessionFile, entries, error, skipped } of results) {
      if (skipped) continue
      if (error || !entries) {
        logForDebugging(
          `Failed to read session file ${sessionFile}: ${errorMessage(error)}`,
        )
        continue
      }

      const sessionId = basename(sessionFile, '.jsonl')
      const messages: TranscriptMessage[] = []

      for (const entry of entries) {
        if (isTranscriptMessage(entry)) {
          messages.push(entry as unknown as TranscriptMessage)
        } else if (entry.type === 'speculation-accept') {
          totalSpeculationTimeSavedMs += (entry as SpeculationAcceptEntry).timeSavedMs
        }
      }

      if (messages.length === 0) continue

      // Los transcripts de subagente marcan todos los mensajes como
      // sidechain. Igual se quiere contar su uso de tokens, pero no como
      // sesiones separadas.
      const isSubagentFile = sessionFile.includes(`${sep}subagents${sep}`)

      // Filtra mensajes sidechain para metadata de sesión (duración,
      // conteos). Para archivos de subagente, usa todos los mensajes
      // porque todos son sidechain.
      const mainMessages = isSubagentFile
        ? messages
        : messages.filter(m => !m.isSidechain)
      if (mainMessages.length === 0) continue

      const firstMessage = mainMessages[0]!
      const lastMessage = mainMessages.at(-1)!

      const firstTimestamp = new Date(firstMessage.timestamp)
      const lastTimestamp = new Date(lastMessage.timestamp)

      // Se saltan sesiones con timestamps malformados — algunos
      // transcripts en disco tienen entradas sin el campo timestamp
      // (p. ej. escrituras parciales/remotas). new Date(undefined)
      // produce un Invalid Date, y toDateString() lanzaría RangeError.
      if (isNaN(firstTimestamp.getTime()) || isNaN(lastTimestamp.getTime())) {
        logForDebugging(
          `Skipping session with invalid timestamp: ${sessionFile}`,
        )
        continue
      }

      const dateKey = toDateString(firstTimestamp)

      if (fromDate && isDateBefore(dateKey, fromDate)) continue
      if (toDate && isDateBefore(toDate, dateKey)) continue

      const existing = dailyActivityMap.get(dateKey) || {
        date: dateKey,
        messageCount: 0,
        sessionCount: 0,
        toolCallCount: 0,
      }

      // Los archivos de subagente contribuyen tokens y tool calls, pero
      // no son sesiones.
      if (!isSubagentFile) {
        const duration = lastTimestamp.getTime() - firstTimestamp.getTime()

        sessions.push({
          sessionId,
          duration,
          messageCount: mainMessages.length,
          timestamp: firstMessage.timestamp,
        })

        totalMessages += mainMessages.length

        existing.sessionCount++
        existing.messageCount += mainMessages.length

        const hour = firstTimestamp.getHours()
        hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1)
      }

      if (!isSubagentFile || dailyActivityMap.has(dateKey)) {
        dailyActivityMap.set(dateKey, existing)
      }

      // Procesa mensajes para uso de herramientas y stats de modelo.
      for (const message of mainMessages) {
        if (message.type === 'assistant') {
          const content = message.message?.content
          if (Array.isArray(content)) {
            for (const block of content) {
              if (block.type === 'tool_use') {
                const activity = dailyActivityMap.get(dateKey)
                if (activity) {
                  activity.toolCallCount++
                }
              }
            }
          }

          // Rastrea uso de modelo si está disponible (salta mensajes sintéticos).
          if (message.message?.usage) {
            const usage = message.message.usage as Record<string, number>
            const model = (message.message.model as string) || 'unknown'

            if (model === SYNTHETIC_MODEL) {
              continue
            }

            if (!modelUsageAgg[model]) {
              modelUsageAgg[model] = {
                inputTokens: 0,
                outputTokens: 0,
                cacheReadInputTokens: 0,
                cacheCreationInputTokens: 0,
                webSearchRequests: 0,
                costUSD: 0,
                contextWindow: 0,
                maxOutputTokens: 0,
              }
            }

            modelUsageAgg[model]!.inputTokens += usage.input_tokens || 0
            modelUsageAgg[model]!.outputTokens += usage.output_tokens || 0
            modelUsageAgg[model]!.cacheReadInputTokens +=
              usage.cache_read_input_tokens || 0
            modelUsageAgg[model]!.cacheCreationInputTokens +=
              usage.cache_creation_input_tokens || 0

            const totalTokens =
              (usage.input_tokens || 0) + (usage.output_tokens || 0)
            if (totalTokens > 0) {
              const dayTokens = dailyModelTokensMap.get(dateKey) || {}
              dayTokens[model] = (dayTokens[model] || 0) + totalTokens
              dailyModelTokensMap.set(dateKey, dayTokens)
            }
          }
        }
      }
    }
  }

  return {
    dailyActivity: Array.from(dailyActivityMap.values()).sort((a, b) =>
      a.date.localeCompare(b.date),
    ),
    dailyModelTokens: Array.from(dailyModelTokensMap.entries())
      .map(([date, tokensByModel]) => ({ date, tokensByModel }))
      .sort((a, b) => a.date.localeCompare(b.date)),
    modelUsage: modelUsageAgg,
    sessionStats: sessions,
    hourCounts: Object.fromEntries(hourCounts),
    totalMessages,
    totalSpeculationTimeSavedMs,
  }
}

/**
 * Obtiene todos los archivos de sesión de todos los directorios de
 * proyecto. Incluye archivos de sesión principales y de transcript de
 * subagente.
 */
async function getAllSessionFiles(): Promise<string[]> {
  const projectsDir = getProjectsDir()
  const fs = getFsImplementation()

  let allEntries
  try {
    allEntries = await fs.readdir(projectsDir)
  } catch (e) {
    if (isENOENT(e)) return []
    throw e
  }
  const projectDirs = allEntries
    .filter(dirent => dirent.isDirectory())
    .map(dirent => join(projectsDir, dirent.name))

  const projectResults = await Promise.all(
    projectDirs.map(async projectDir => {
      try {
        const entries = await fs.readdir(projectDir)

        const mainFiles = entries
          .filter(dirent => dirent.isFile() && dirent.name.endsWith('.jsonl'))
          .map(dirent => join(projectDir, dirent.name))

        // Estructura: {projectDir}/{sessionId}/subagents/agent-{agentId}.jsonl
        const sessionDirs = entries.filter(dirent => dirent.isDirectory())
        const subagentResults = await Promise.all(
          sessionDirs.map(async sessionDir => {
            const subagentsDir = join(projectDir, sessionDir.name, 'subagents')
            try {
              const subagentEntries = await fs.readdir(subagentsDir)
              return subagentEntries
                .filter(
                  dirent =>
                    dirent.isFile() &&
                    dirent.name.endsWith('.jsonl') &&
                    dirent.name.startsWith('agent-'),
                )
                .map(dirent => join(subagentsDir, dirent.name))
            } catch {
              return []
            }
          }),
        )

        return [...mainFiles, ...subagentResults.flat()]
      } catch (error) {
        logForDebugging(
          `Failed to read project directory ${projectDir}: ${errorMessage(error)}`,
        )
        return []
      }
    }),
  )

  return projectResults.flat()
}

/** Convierte una PersistedStatsCache a ClaudeCodeStats computando campos derivados. */
function cacheToStats(
  cache: PersistedStatsCache,
  todayStats: ProcessedStats | null,
): ClaudeCodeStats {
  const dailyActivityMap = new Map<string, DailyActivity>()
  for (const day of cache.dailyActivity) {
    dailyActivityMap.set(day.date, { ...day })
  }
  if (todayStats) {
    for (const day of todayStats.dailyActivity) {
      const existing = dailyActivityMap.get(day.date)
      if (existing) {
        existing.messageCount += day.messageCount
        existing.sessionCount += day.sessionCount
        existing.toolCallCount += day.toolCallCount
      } else {
        dailyActivityMap.set(day.date, { ...day })
      }
    }
  }

  const dailyModelTokensMap = new Map<string, { [model: string]: number }>()
  for (const day of cache.dailyModelTokens) {
    dailyModelTokensMap.set(day.date, { ...day.tokensByModel })
  }
  if (todayStats) {
    for (const day of todayStats.dailyModelTokens) {
      const existing = dailyModelTokensMap.get(day.date)
      if (existing) {
        for (const [model, tokens] of Object.entries(day.tokensByModel)) {
          existing[model] = (existing[model] || 0) + tokens
        }
      } else {
        dailyModelTokensMap.set(day.date, { ...day.tokensByModel })
      }
    }
  }

  const modelUsage = { ...cache.modelUsage }
  if (todayStats) {
    for (const [model, usage] of Object.entries(todayStats.modelUsage)) {
      if (modelUsage[model]) {
        modelUsage[model] = {
          inputTokens: modelUsage[model]!.inputTokens + usage.inputTokens,
          outputTokens: modelUsage[model]!.outputTokens + usage.outputTokens,
          cacheReadInputTokens:
            modelUsage[model]!.cacheReadInputTokens +
            usage.cacheReadInputTokens,
          cacheCreationInputTokens:
            modelUsage[model]!.cacheCreationInputTokens +
            usage.cacheCreationInputTokens,
          webSearchRequests:
            modelUsage[model]!.webSearchRequests + usage.webSearchRequests,
          costUSD: modelUsage[model]!.costUSD + usage.costUSD,
          contextWindow: Math.max(
            modelUsage[model]!.contextWindow,
            usage.contextWindow,
          ),
          maxOutputTokens: Math.max(
            modelUsage[model]!.maxOutputTokens,
            usage.maxOutputTokens,
          ),
        }
      } else {
        modelUsage[model] = { ...usage }
      }
    }
  }

  const hourCountsMap = new Map<number, number>()
  for (const [hour, count] of Object.entries(cache.hourCounts)) {
    hourCountsMap.set(parseInt(hour, 10), count)
  }
  if (todayStats) {
    for (const [hour, count] of Object.entries(todayStats.hourCounts)) {
      const hourNum = parseInt(hour, 10)
      hourCountsMap.set(hourNum, (hourCountsMap.get(hourNum) || 0) + count)
    }
  }

  const dailyActivityArray = Array.from(dailyActivityMap.values()).sort(
    (a, b) => a.date.localeCompare(b.date),
  )
  const streaks = calculateStreaks(dailyActivityArray)

  const dailyModelTokens = Array.from(dailyModelTokensMap.entries())
    .map(([date, tokensByModel]) => ({ date, tokensByModel }))
    .sort((a, b) => a.date.localeCompare(b.date))

  const totalSessions =
    cache.totalSessions + (todayStats?.sessionStats.length || 0)
  const totalMessages = cache.totalMessages + (todayStats?.totalMessages || 0)

  let longestSession = cache.longestSession
  if (todayStats) {
    for (const session of todayStats.sessionStats) {
      if (!longestSession || session.duration > longestSession.duration) {
        longestSession = session
      }
    }
  }

  let firstSessionDate = cache.firstSessionDate
  let lastSessionDate: string | null = null
  if (todayStats) {
    for (const session of todayStats.sessionStats) {
      if (!firstSessionDate || session.timestamp < firstSessionDate) {
        firstSessionDate = session.timestamp
      }
      if (!lastSessionDate || session.timestamp > lastSessionDate) {
        lastSessionDate = session.timestamp
      }
    }
  }
  if (!lastSessionDate && dailyActivityArray.length > 0) {
    lastSessionDate = dailyActivityArray.at(-1)!.date
  }

  const peakActivityDay =
    dailyActivityArray.length > 0
      ? dailyActivityArray.reduce((max, d) =>
          d.messageCount > max.messageCount ? d : max,
        ).date
      : null

  const peakActivityHour =
    hourCountsMap.size > 0
      ? Array.from(hourCountsMap.entries()).reduce((max, [hour, count]) =>
          count > max[1] ? [hour, count] : max,
        )[0]
      : null

  const totalDays =
    firstSessionDate && lastSessionDate
      ? Math.ceil(
          (new Date(lastSessionDate).getTime() -
            new Date(firstSessionDate).getTime()) /
            (1000 * 60 * 60 * 24),
        ) + 1
      : 0

  const totalSpeculationTimeSavedMs =
    cache.totalSpeculationTimeSavedMs +
    (todayStats?.totalSpeculationTimeSavedMs || 0)

  const result: ClaudeCodeStats = {
    totalSessions,
    totalMessages,
    totalDays,
    activeDays: dailyActivityMap.size,
    streaks,
    dailyActivity: dailyActivityArray,
    dailyModelTokens,
    longestSession,
    modelUsage,
    firstSessionDate,
    lastSessionDate,
    peakActivityDay,
    peakActivityHour,
    totalSpeculationTimeSavedMs,
  }

  return result
}

/**
 * Agrega stats de todas las sesiones de Claude Code en todos los
 * proyectos. Usa una caché en disco para evitar reprocesar datos
 * históricos.
 */
export async function aggregateClaudeCodeStats(): Promise<ClaudeCodeStats> {
  const allSessionFiles = await getAllSessionFiles()

  if (allSessionFiles.length === 0) {
    return getEmptyStats()
  }

  // Usa lock para prevenir condiciones de carrera con actualizaciones de
  // caché en background.
  const updatedCache = await withStatsCacheLock(async () => {
    const cache = await loadStatsCache()
    const yesterday = getYesterdayDateString()

    let result = cache

    if (!cache.lastComputedDate) {
      logForDebugging('Stats cache empty, processing all historical data')
      const historicalStats = await processSessionFiles(allSessionFiles, {
        toDate: yesterday,
      })

      if (
        historicalStats.sessionStats.length > 0 ||
        historicalStats.dailyActivity.length > 0
      ) {
        result = mergeCacheWithNewStats(cache, historicalStats, yesterday)
        await saveStatsCache(result)
      }
    } else if (isDateBefore(cache.lastComputedDate, yesterday)) {
      const nextDay = getNextDay(cache.lastComputedDate)
      logForDebugging(
        `Stats cache stale (${cache.lastComputedDate}), processing ${nextDay} to ${yesterday}`,
      )
      const newStats = await processSessionFiles(allSessionFiles, {
        fromDate: nextDay,
        toDate: yesterday,
      })

      if (
        newStats.sessionStats.length > 0 ||
        newStats.dailyActivity.length > 0
      ) {
        result = mergeCacheWithNewStats(cache, newStats, yesterday)
        await saveStatsCache(result)
      } else {
        result = { ...cache, lastComputedDate: yesterday }
        await saveStatsCache(result)
      }
    }

    return result
  })

  // Siempre procesa los datos de hoy en vivo (están incompletos). No
  // necesita estar dentro del lock porque no modifica la caché.
  const today = getTodayDateString()
  const todayStats = await processSessionFiles(allSessionFiles, {
    fromDate: today,
    toDate: today,
  })

  return cacheToStats(updatedCache, todayStats)
}

export type StatsDateRange = '7d' | '30d' | 'all'

/**
 * Agrega stats para un rango de fechas específico. Para 'all', usa la
 * agregación cacheada. Para otros rangos, procesa archivos directamente.
 */
export async function aggregateClaudeCodeStatsForRange(
  range: StatsDateRange,
): Promise<ClaudeCodeStats> {
  if (range === 'all') {
    return aggregateClaudeCodeStats()
  }

  const allSessionFiles = await getAllSessionFiles()
  if (allSessionFiles.length === 0) {
    return getEmptyStats()
  }

  const today = new Date()
  const daysBack = range === '7d' ? 7 : 30
  const fromDate = new Date(today)
  fromDate.setDate(today.getDate() - daysBack + 1) // +1 para incluir hoy
  const fromDateStr = toDateString(fromDate)

  const stats = await processSessionFiles(allSessionFiles, {
    fromDate: fromDateStr,
  })

  return processedStatsToClaudeCodeStats(stats)
}

/**
 * Convierte ProcessedStats a ClaudeCodeStats. Se usa para rangos de
 * fecha filtrados que evitan la caché.
 */
function processedStatsToClaudeCodeStats(
  stats: ProcessedStats,
): ClaudeCodeStats {
  const dailyActivitySorted = stats.dailyActivity
    .slice()
    .sort((a, b) => a.date.localeCompare(b.date))
  const dailyModelTokensSorted = stats.dailyModelTokens
    .slice()
    .sort((a, b) => a.date.localeCompare(b.date))

  const streaks = calculateStreaks(dailyActivitySorted)

  let longestSession: SessionStats | null = null
  for (const session of stats.sessionStats) {
    if (!longestSession || session.duration > longestSession.duration) {
      longestSession = session
    }
  }

  let firstSessionDate: string | null = null
  let lastSessionDate: string | null = null
  for (const session of stats.sessionStats) {
    if (!firstSessionDate || session.timestamp < firstSessionDate) {
      firstSessionDate = session.timestamp
    }
    if (!lastSessionDate || session.timestamp > lastSessionDate) {
      lastSessionDate = session.timestamp
    }
  }

  const peakActivityDay =
    dailyActivitySorted.length > 0
      ? dailyActivitySorted.reduce((max, d) =>
          d.messageCount > max.messageCount ? d : max,
        ).date
      : null

  const hourEntries = Object.entries(stats.hourCounts)
  const peakActivityHour =
    hourEntries.length > 0
      ? parseInt(
          hourEntries.reduce((max, [hour, count]) =>
            count > parseInt(max[1].toString(), 10) ? [hour, count] : max,
          )[0],
          10,
        )
      : null

  const totalDays =
    firstSessionDate && lastSessionDate
      ? Math.ceil(
          (new Date(lastSessionDate).getTime() -
            new Date(firstSessionDate).getTime()) /
            (1000 * 60 * 60 * 24),
        ) + 1
      : 0

  const result: ClaudeCodeStats = {
    totalSessions: stats.sessionStats.length,
    totalMessages: stats.totalMessages,
    totalDays,
    activeDays: stats.dailyActivity.length,
    streaks,
    dailyActivity: dailyActivitySorted,
    dailyModelTokens: dailyModelTokensSorted,
    longestSession,
    modelUsage: stats.modelUsage,
    firstSessionDate,
    lastSessionDate,
    peakActivityDay,
    peakActivityHour,
    totalSpeculationTimeSavedMs: stats.totalSpeculationTimeSavedMs,
  }

  return result
}

/** Obtiene el día siguiente a una cadena de fecha dada (formato YYYY-MM-DD). */
function getNextDay(dateStr: string): string {
  const date = new Date(dateStr)
  date.setDate(date.getDate() + 1)
  return toDateString(date)
}

function calculateStreaks(dailyActivity: DailyActivity[]): StreakInfo {
  if (dailyActivity.length === 0) {
    return {
      currentStreak: 0,
      longestStreak: 0,
      currentStreakStart: null,
      longestStreakStart: null,
      longestStreakEnd: null,
    }
  }

  const today = new Date()
  today.setHours(0, 0, 0, 0)

  let currentStreak = 0
  let currentStreakStart: string | null = null
  const checkDate = new Date(today)

  const activeDates = new Set(dailyActivity.map(d => d.date))

  while (true) {
    const dateStr = toDateString(checkDate)
    if (!activeDates.has(dateStr)) {
      break
    }
    currentStreak++
    currentStreakStart = dateStr
    checkDate.setDate(checkDate.getDate() - 1)
  }

  let longestStreak = 0
  let longestStreakStart: string | null = null
  let longestStreakEnd: string | null = null

  if (dailyActivity.length > 0) {
    const sortedDates = Array.from(activeDates).sort()
    let tempStreak = 1
    let tempStart = sortedDates[0]!

    for (let i = 1; i < sortedDates.length; i++) {
      const prevDate = new Date(sortedDates[i - 1]!)
      const currDate = new Date(sortedDates[i]!)

      const dayDiff = Math.round(
        (currDate.getTime() - prevDate.getTime()) / (1000 * 60 * 60 * 24),
      )

      if (dayDiff === 1) {
        tempStreak++
      } else {
        if (tempStreak > longestStreak) {
          longestStreak = tempStreak
          longestStreakStart = tempStart
          longestStreakEnd = sortedDates[i - 1]!
        }
        tempStreak = 1
        tempStart = sortedDates[i]!
      }
    }

    if (tempStreak > longestStreak) {
      longestStreak = tempStreak
      longestStreakStart = tempStart
      longestStreakEnd = sortedDates.at(-1)!
    }
  }

  return {
    currentStreak,
    longestStreak,
    currentStreakStart,
    longestStreakStart,
    longestStreakEnd,
  }
}

// Tipos de mensaje de transcript — deben coincidir con isTranscriptMessage()
// en sessionStorage.ts. El dateKey canónico (ver processSessionFiles) lee
// mainMessages[0].timestamp, donde mainMessages =
// entries.filter(isTranscriptMessage).filter(!isSidechain). Este espiado
// debe extraer el mismo valor para ser una optimización de salto segura.
//
// NOTA DE DISCREPANCIA DE LA FUENTE (ver docstring del módulo): el
// comentario de arriba dice "must match isTranscriptMessage()" pero el
// Set real de la fuente incluye 'progress', que `isTranscriptMessage`
// EXCLUYE explícitamente (`sessionStoragePredicates.ts:21-27`). Se porta
// el Set exacto, verbatim a la fuente.
const TRANSCRIPT_MESSAGE_TYPES = new Set([
  'user',
  'assistant',
  'attachment',
  'system',
  'progress',
])

/**
 * Espía el inicio de un archivo de sesión para obtener la fecha de
 * inicio de la sesión. Usa una lectura pequeña de 4 KB para evitar
 * cargar el archivo completo.
 *
 * Los archivos de sesión típicamente empiezan con entradas que no son
 * de transcript (`mode`, `file-history-snapshot`, `attribution-snapshot`)
 * antes del primer mensaje de transcript, así que se recorren líneas
 * hasta encontrar una. Cada línea completa se parsea como JSON — una
 * búsqueda ingenua por cadena no es segura aquí porque las entradas
 * `file-history-snapshot` embeben un `snapshot.timestamp` anidado que
 * lleva la fecha de la sesión ANTERIOR (escrito por
 * copyFileHistoryForResume), lo que haría que sesiones retomadas se
 * clasificaran mal como viejas y se descartaran en silencio de las stats.
 *
 * Devuelve una cadena YYYY-MM-DD, o null si ningún mensaje de transcript
 * cabe en el inicio (el llamador cae al camino de lectura completa —
 * default seguro).
 */
export async function readSessionStartDate(
  filePath: string,
): Promise<string | null> {
  try {
    const fd = await open(filePath, 'r')
    try {
      const buf = Buffer.allocUnsafe(4096)
      const { bytesRead } = await fd.read(buf, 0, buf.length, 0)
      if (bytesRead === 0) return null
      const head = buf.toString('utf8', 0, bytesRead)

      // Sólo confía en líneas completas — la frontera de 4KB puede
      // partir una entrada JSON en dos.
      const lastNewline = head.lastIndexOf('\n')
      if (lastNewline < 0) return null

      for (const line of head.slice(0, lastNewline).split('\n')) {
        if (!line) continue
        let entry: {
          type?: unknown
          timestamp?: unknown
          isSidechain?: unknown
        }
        try {
          entry = jsonParse(line)
        } catch {
          continue
        }
        if (typeof entry.type !== 'string') continue
        if (!TRANSCRIPT_MESSAGE_TYPES.has(entry.type)) continue
        if (entry.isSidechain === true) continue
        if (typeof entry.timestamp !== 'string') return null
        const date = new Date(entry.timestamp)
        if (Number.isNaN(date.getTime())) return null
        return toDateString(date)
      }
      return null
    } finally {
      await fd.close()
    }
  } catch {
    return null
  }
}

