/**
 * Gets the display title for a log/session with fallback logic.
 * Skips firstPrompt if it starts with a tick/goal tag (autonomous mode auto-prompt).
 * Strips display-unfriendly tags (like <ide_opened_file>) from the result.
 * Falls back to a truncated session ID when no other title is available.
 */
export function getLogDisplayTitle(
  log: LogOption,
  defaultTitle?: string,
): string {
  const isAutonomousPrompt = log.firstPrompt?.startsWith(`<${TICK_TAG}>`)
  const strippedFirstPrompt = log.firstPrompt
    ? stripDisplayTagsAllowEmpty(log.firstPrompt)
    : ''
  const useFirstPrompt = strippedFirstPrompt && !isAutonomousPrompt
  const title =
    log.agentName ||
    log.customTitle ||
    log.summary ||
    (useFirstPrompt ? strippedFirstPrompt : undefined) ||
    defaultTitle ||
    (isAutonomousPrompt ? 'Autonomous session' : undefined) ||
    (log.sessionId ? log.sessionId.slice(0, 8) : '') ||
    ''
  return stripDisplayTags(title).trim()
}

/**
 * Loads the list of error logs.
 */
export function loadErrorLogs(): Promise<LogOption[]> {
  return loadLogList(CACHE_PATHS.errors())
}

/**
 * Gets an error log by its index.
 */
export async function getErrorLogByIndex(
  index: number,
): Promise<LogOption | null> {
  const logs = await loadErrorLogs()
  return logs[index] || null
}

async function loadLogList(path: string): Promise<LogOption[]> {
  let files: Dirent[]
  try {
    files = await readdir(path, { withFileTypes: true })
  } catch {
    logError(new Error(`No logs found at ${path}`))
    return []
  }
  const logData = await Promise.all(
    files.map(async (file, i) => {
      const fullPath = join(path, String(file.name))
      const content = await readFile(fullPath, { encoding: 'utf8' })
      const messages = jsonParse(content) as SerializedMessage[]
      const firstMessage = messages[0]
      const lastMessage = messages[messages.length - 1]
      const firstPrompt =
        firstMessage?.type === 'user' &&
        typeof firstMessage?.message?.content === 'string'
          ? firstMessage?.message?.content
          : 'No prompt'

      const fileStats = await stat(fullPath)
      const isSidechain = fullPath.includes('sidechain')
      const date = dateToFilename(fileStats.mtime)

      return {
        date,
        fullPath,
        messages,
        value: i,
        created: parseISOString(firstMessage?.timestamp || date),
        modified: lastMessage?.timestamp
          ? parseISOString(lastMessage.timestamp)
          : parseISOString(date),
        firstPrompt:
          firstPrompt.split('\n')[0]?.slice(0, 50) +
            (firstPrompt.length > 50 ? '…' : '') || 'No prompt',
        messageCount: messages.length,
        isSidechain,
      }
    }),
  )

  return sortLogs(logData.filter(_ => _ !== null)).map((_, i) => ({
    ..._,
    value: i,
  }))
}

function parseISOString(s: string): Date {
  const b = s.split(/\D+/)
  return new Date(
    Date.UTC(
      parseInt(b[0]!, 10),
      parseInt(b[1]!, 10) - 1,
      parseInt(b[2]!, 10),
      parseInt(b[3]!, 10),
      parseInt(b[4]!, 10),
      parseInt(b[5]!, 10),
      parseInt(b[6]!, 10),
    ),
  )
}

import { describe, expect, test } from 'bun:test'
import {
  partiallySanitizeUnicode,
  recursivelySanitizeUnicode,
} from '../sanitization.js'

describe('partiallySanitizeUnicode — passes legitimate content through', () => {
  test('plain ASCII unchanged', () => {
    expect(partiallySanitizeUnicode('hello world')).toBe('hello world')
  })
  test('legitimate non-ASCII preserved', () => {
    expect(partiallySanitizeUnicode('café 中文 🎉')).toBe('café 中文 🎉')
  })
  test('empty string is empty', () => {
    expect(partiallySanitizeUnicode('')).toBe('')
  })
  test('newlines and tabs survive', () => {
    expect(partiallySanitizeUnicode('a\nb\tc')).toBe('a\nb\tc')
  })
})

describe('partiallySanitizeUnicode — strips dangerous categories', () => {
  test('strips zero-width space', () => {
    expect(partiallySanitizeUnicode('hi\u200Bthere')).toBe('hithere')
  })
  test('strips zero-width joiner', () => {
    expect(partiallySanitizeUnicode('a\u200Db')).toBe('ab')
  })
  test('strips byte order mark (BOM)', () => {
    expect(partiallySanitizeUnicode('\uFEFFhello')).toBe('hello')
  })
  test('strips left-to-right mark', () => {
    expect(partiallySanitizeUnicode('a\u200Eb')).toBe('ab')
  })
  test('strips directional override (RTL attack)', () => {
    expect(partiallySanitizeUnicode('a\u202Eb')).toBe('ab')
  })
  test('strips directional isolates', () => {
    expect(partiallySanitizeUnicode('a\u2066b\u2069c')).toBe('abc')
  })
  test('strips private-use BMP characters (Unicode tag attack)', () => {
    // \uE000 is in private-use range
    expect(partiallySanitizeUnicode('safe\uE001hidden')).toBe('safehidden')
  })
})

describe('partiallySanitizeUnicode — NFKC normalization', () => {
  test('decomposes compatibility characters (full-width letters)', () => {
    // ｈｅｌｌｏ (full-width) → hello
    expect(partiallySanitizeUnicode('\uFF48\uFF45\uFF4C\uFF4C\uFF4F')).toBe(
      'hello',
    )
  })
  test('combines diacritics (e + combining acute → é)', () => {
    expect(partiallySanitizeUnicode('e\u0301')).toBe('é')
  })
})

describe('partiallySanitizeUnicode — convergence safety', () => {
  test('idempotent (sanitizing twice equals once)', () => {
    const input = 'safe\u200Bword'
    const once = partiallySanitizeUnicode(input)
    const twice = partiallySanitizeUnicode(once)
    expect(once).toBe(twice)
  })
})

describe('recursivelySanitizeUnicode — strings', () => {
  test('passes through to partiallySanitizeUnicode for strings', () => {
    expect(recursivelySanitizeUnicode('hi\u200Bthere')).toBe('hithere')
  })
  test('returns numbers unchanged', () => {
    expect(recursivelySanitizeUnicode(42)).toBe(42)
  })
  test('returns booleans unchanged', () => {
    expect(recursivelySanitizeUnicode(true)).toBe(true)
  })
  test('returns null unchanged', () => {
    expect(recursivelySanitizeUnicode(null)).toBeNull()
  })
  test('returns undefined unchanged', () => {
    expect(recursivelySanitizeUnicode(undefined)).toBeUndefined()
  })
})

describe('recursivelySanitizeUnicode — arrays', () => {
  test('sanitizes string elements', () => {
    expect(recursivelySanitizeUnicode(['a\u200Bb', 'c'])).toEqual(['ab', 'c'])
  })
  test('preserves non-string elements', () => {
    expect(recursivelySanitizeUnicode([1, 'a\u200Bb', null])).toEqual([
      1,
      'ab',
      null,
    ])
  })
  test('recurses into nested arrays', () => {
    expect(recursivelySanitizeUnicode([['a\u200Bb']])).toEqual([['ab']])
  })
})

describe('recursivelySanitizeUnicode — objects', () => {
  test('sanitizes both keys and values', () => {
    const input: Record<string, string> = {
      'key\u200Bone': 'val\u200Bue',
    }
    const result = recursivelySanitizeUnicode(input)
    expect(result).toEqual({ keyone: 'value' })
  })
  test('recurses into nested objects', () => {
    expect(
      recursivelySanitizeUnicode({ outer: { inner: 'a\u200Bb' } }),
    ).toEqual({ outer: { inner: 'ab' } })
  })
  test('preserves primitive values in objects', () => {
    expect(recursivelySanitizeUnicode({ n: 42, b: true })).toEqual({
      n: 42,
      b: true,
    })
  })
})

/**
 * Tests for mcp-runtime/utils.ts pure helpers.
 *
 * filterToolsByServer / commandBelongsToServer / hashMcpConfig drive
 * /reload-plugins and the "this server's tools" UI. Wrong filtering
 * either leaks tools across server boundaries (auth confusion) or
 * makes a server's tools invisible.
 *
 * hashMcpConfig is the change-detection seed for reconnect-on-edit.
 * A regression that ignores keys or includes `scope` would either
 * miss real edits (server stays stale) or reconnect spuriously
 * (provenance change ≠ config change).
 */
import { describe, expect, test } from 'bun:test'
import type { Command } from '../types.js'
import type { Tool } from '../types.js'
import {
  commandBelongsToServer,
  excludeToolsByServer,
  filterCommandsByServer,
  filterToolsByServer,
  hashMcpConfig,
} from '../utils.js'

function tool(name: string): Tool {
  return { name } as Tool
}

function cmd(name: string, extra: Partial<Command> = {}): Command {
  return { name, ...extra } as Command
}

describe('filterToolsByServer', () => {
  test('matches mcp__server__tool prefix', () => {
    const tools = [
      tool('mcp__github__list_issues'),
      tool('mcp__gitlab__list_issues'),
      tool('mcp__github__create_pr'),
    ]
    const result = filterToolsByServer(tools, 'github')
    expect(result).toHaveLength(2)
    expect(result.map(t => t.name)).toEqual([
      'mcp__github__list_issues',
      'mcp__github__create_pr',
    ])
  })

  test('non-MCP tools (no prefix) are excluded', () => {
    expect(filterToolsByServer([tool('Bash'), tool('Edit')], 'github')).toEqual(
      [],
    )
  })

  test('server name with chars normalized', () => {
    // normalizeNameForMCP replaces non-allowlist chars with `_`. So a
    // server "my-server" matches `mcp__my-server__*` (dashes are kept
    // by the normalizer's [a-zA-Z0-9_-] allowlist).
    const tools = [tool('mcp__my-server__do_thing')]
    expect(filterToolsByServer(tools, 'my-server')).toHaveLength(1)
  })

  test('empty tools array returns empty', () => {
    expect(filterToolsByServer([], 'github')).toEqual([])
  })

  test('tool with undefined name is filtered out (no startsWith on undefined)', () => {
    const t = { name: undefined } as Partial<Tool> as Tool
    expect(filterToolsByServer([t], 'github')).toEqual([])
  })
})

describe('commandBelongsToServer — mcp__ AND server: prefixes', () => {
  test('mcp__server__cmd matches', () => {
    expect(commandBelongsToServer(cmd('mcp__github__test'), 'github')).toBe(true)
  })

  test('server:cmd (skill format) matches', () => {
    // MCP skills use `<server>:<skill>` (matches plugin/nested-dir
    // skill naming).
    expect(commandBelongsToServer(cmd('github:list_issues'), 'github')).toBe(
      true,
    )
  })

  test('different server → false', () => {
    expect(commandBelongsToServer(cmd('mcp__gitlab__test'), 'github')).toBe(
      false,
    )
  })

  test('no name → false', () => {
    expect(commandBelongsToServer(cmd(''), 'github')).toBe(false)
  })
})

describe('filterCommandsByServer', () => {
  test('mixes both name shapes', () => {
    const commands = [
      cmd('mcp__github__list_prs'),
      cmd('github:create_pr'),
      cmd('mcp__gitlab__list_issues'),
      cmd('local_command'),
    ]
    const result = filterCommandsByServer(commands, 'github')
    expect(result).toHaveLength(2)
  })
})

describe('excludeToolsByServer — inverse filter', () => {
  test('removes only the named server', () => {
    const tools = [
      tool('mcp__github__a'),
      tool('mcp__gitlab__b'),
      tool('Bash'),
    ]
    const result = excludeToolsByServer(tools, 'github')
    expect(result.map(t => t.name)).toEqual(['mcp__gitlab__b', 'Bash'])
  })

  test('empty → empty', () => {
    expect(excludeToolsByServer([], 'github')).toEqual([])
  })
})

describe('hashMcpConfig — stable change-detection', () => {
  test('same content → same hash', () => {
    const a = { scope: 'user', command: 'node', args: ['x'] } as never
    const b = { scope: 'user', command: 'node', args: ['x'] } as never
    expect(hashMcpConfig(a)).toBe(hashMcpConfig(b))
  })

  test('scope is EXCLUDED from hash (provenance, not content)', () => {
    // Documented: moving a server from .mcp.json to settings.json
    // shouldn't reconnect it.
    const userScope = { scope: 'user', command: 'x' } as never
    const projectScope = { scope: 'project', command: 'x' } as never
    expect(hashMcpConfig(userScope)).toBe(hashMcpConfig(projectScope))
  })

  test('different command → different hash', () => {
    const a = { scope: 'user', command: 'a' } as never
    const b = { scope: 'user', command: 'b' } as never
    expect(hashMcpConfig(a)).not.toBe(hashMcpConfig(b))
  })

  test('key order in nested objects does NOT affect hash (sorted)', () => {
    // Documented: keys sorted so {a:1,b:2} and {b:2,a:1} hash the same.
    const a = {
      scope: 'user',
      env: { PATH: '/x', NODE_OPTIONS: '--max-old-space-size=4096' },
    } as never
    const b = {
      scope: 'user',
      env: { NODE_OPTIONS: '--max-old-space-size=4096', PATH: '/x' },
    } as never
    expect(hashMcpConfig(a)).toBe(hashMcpConfig(b))
  })

  test('hash is 16 hex chars (sliced from sha256)', () => {
    const h = hashMcpConfig({ scope: 'user', command: 'x' } as never)
    expect(h).toMatch(/^[0-9a-f]{16}$/)
  })

  test('changing nested env value → hash changes', () => {
    const a = { scope: 'user', env: { PATH: '/a' } } as never
    const b = { scope: 'user', env: { PATH: '/b' } } as never
    expect(hashMcpConfig(a)).not.toBe(hashMcpConfig(b))
  })
})

import { getMcpRuntimeHostBindings } from './host.js'
import { HostBindingsError } from './errors.js'

export async function getMcpToolsCommandsAndResources<
  TMcpTool,
  TMcpCommand,
  TMcpResource,
  TMcpConfig,
  TMcpConnection,
>(
  onConnectionAttempt: (params: {
    client: TMcpConnection
    tools: TMcpTool[]
    commands: TMcpCommand[]
    resources?: TMcpResource[]
  }) => void,
  sdkMcpConfigs?: Record<string, TMcpConfig>,
): Promise<void> {
  return getMcpRuntimeHostBindings<
    TMcpTool,
    TMcpCommand,
    TMcpResource,
    TMcpConfig,
    TMcpConnection
  >().getMcpToolsCommandsAndResources(onConnectionAttempt, sdkMcpConfigs)
}

export async function prefetchAllMcpResources<
  TMcpTool,
  TMcpCommand,
  TMcpConfig,
  TMcpConnection,
>(
  mcpConfigs: Record<string, TMcpConfig>,
): Promise<{
  clients: TMcpConnection[]
  tools: TMcpTool[]
  commands: TMcpCommand[]
}> {
  return getMcpRuntimeHostBindings<
    TMcpTool,
    TMcpCommand,
    unknown,
    TMcpConfig,
    TMcpConnection
  >().prefetchAllMcpResources(mcpConfigs)
}

export async function connectAll<TMcpConfig, TMcpConnection>(
  configs: Record<string, TMcpConfig>,
): Promise<TMcpConnection[]> {
  const host = getMcpRuntimeHostBindings<
    unknown,
    unknown,
    unknown,
    TMcpConfig,
    TMcpConnection
  >()

  if (host.connectAll) {
    return host.connectAll(configs)
  }

  const clients: TMcpConnection[] = []
  await host.getMcpToolsCommandsAndResources(({ client }) => {
    clients.push(client)
  }, configs)
  return clients
}

export async function discover<
  TMcpTool,
  TMcpCommand,
  TMcpResource,
  TMcpConfig,
  TMcpConnection,
>(
  configs?: Record<string, TMcpConfig>,
): Promise<{
  clients: TMcpConnection[]
  tools: TMcpTool[]
  commands: TMcpCommand[]
  resources?: Record<string, TMcpResource[]>
}> {
  const host = getMcpRuntimeHostBindings<
    TMcpTool,
    TMcpCommand,
    TMcpResource,
    TMcpConfig,
    TMcpConnection
  >()

  if (host.discover) {
    return host.discover(configs)
  }

  const clients: TMcpConnection[] = []
  const tools: TMcpTool[] = []
  const commands: TMcpCommand[] = []
  const resources: Record<string, TMcpResource[]> = {}

  await host.getMcpToolsCommandsAndResources(result => {
    clients.push(result.client)
    tools.push(...result.tools)
    commands.push(...result.commands)
    if (result.resources) {
      // TMcpConnection is generic and doesn't expose `.name` on its
      // base contract; concrete connections do. Falls back to a
      // synthetic key when the impl omits it.
      resources[
        (result.client as { name?: string } | null)?.name ??
          `server-${clients.length}`
      ] = result.resources
    }
  }, configs)

  return {
    clients,
    tools,
    commands,
    ...(Object.keys(resources).length > 0 ? { resources } : {}),
  }
}

export async function executeTool<TMcpConfig>(
  call: {
    serverName: string
    serverConfig: TMcpConfig
    toolName: string
    input: Record<string, unknown>
    meta?: Record<string, unknown>
    signal?: AbortSignal
  },
): Promise<unknown> {
  const host = getMcpRuntimeHostBindings<
    unknown,
    unknown,
    unknown,
    TMcpConfig,
    unknown
  >()
  if (!host.executeTool) {
    throw new HostBindingsError(
      'MCP runtime host binding does not implement executeTool',
    )
  }
  return host.executeTool(call)
}

export async function prefetchResources<
  TMcpTool,
  TMcpCommand,
  TMcpResource,
  TMcpConfig,
  TMcpConnection,
>(
  configs: Record<string, TMcpConfig>,
): Promise<{
  clients: TMcpConnection[]
  tools: TMcpTool[]
  commands: TMcpCommand[]
  resources?: Record<string, TMcpResource[]>
}> {
  const host = getMcpRuntimeHostBindings<
    TMcpTool,
    TMcpCommand,
    TMcpResource,
    TMcpConfig,
    TMcpConnection
  >()

  if (host.prefetchResources) {
    return host.prefetchResources(configs)
  }

  return discover(configs)
}

/**
 * SDK-side mcp_set_servers handler. Delegates to the root-installed
 * implementation (see src/cli/mcpServersHandlers.ts). Callers cast the
 * result to their local concrete type specialization — see V7 §10.2
 * Cut 5 for details on why the types are opaque here.
 */
export async function handleMcpSetServers(
  servers: Record<string, unknown>,
  sdkState: unknown,
  dynamicState: unknown,
  setAppState: (f: (prev: unknown) => unknown) => void,
): Promise<unknown> {
  const host = getMcpRuntimeHostBindings<
    unknown,
    unknown,
    unknown,
    unknown,
    unknown
  >()
  if (!host.handleMcpSetServers) {
    throw new HostBindingsError(
      'MCP runtime host binding does not implement handleMcpSetServers',
    )
  }
  return host.handleMcpSetServers(servers, sdkState, dynamicState, setAppState)
}

export async function reconcileMcpServers(
  desiredConfigs: Record<string, unknown>,
  currentState: unknown,
  setAppState: (f: (prev: unknown) => unknown) => void,
): Promise<unknown> {
  const host = getMcpRuntimeHostBindings<
    unknown,
    unknown,
    unknown,
    unknown,
    unknown
  >()
  if (!host.reconcileMcpServers) {
    throw new HostBindingsError(
      'MCP runtime host binding does not implement reconcileMcpServers',
    )
  }
  return host.reconcileMcpServers(desiredConfigs, currentState, setAppState)
}

