import { describe, expect, test } from 'bun:test'

import {
  permissionBehaviorSchema,
  permissionRuleValueSchema,
} from '../PermissionRule.ts'
import {
  permissionUpdateDestinationSchema,
  permissionUpdateSchema,
} from '../PermissionUpdateSchema.ts'

/**
 * Pin Zod schemas for permission rules and updates. These are the
 * wire format for settings files (`.claude/settings.json`) and CLI
 * args. A regression that widens or narrows the enum silently breaks
 * forwards/backwards compat with shipped settings files.
 *
 * Pinned invariants:
 *  1. permissionBehaviorSchema accepts EXACTLY 'allow' | 'deny' | 'ask'
 *     (no 'prompt' or 'manual' even though both have been considered).
 *  2. permissionRuleValueSchema requires toolName, ruleContent optional.
 *  3. permissionUpdateDestinationSchema accepts EXACTLY 5 destinations.
 *  4. permissionUpdateSchema discriminates on `type` over 6 update kinds.
 *  5. addRules/replaceRules/removeRules carry `behavior` + `rules`.
 *  6. setMode carries `mode` (external permission mode).
 *  7. addDirectories/removeDirectories carry `directories` (string[]).
 */
describe('permission schemas (Zod wire-format pins)', () => {
  describe('permissionBehaviorSchema', () => {
    test('accepts allow/deny/ask (the 3 canonical behaviors)', () => {
      expect(permissionBehaviorSchema().parse('allow')).toBe('allow')
      expect(permissionBehaviorSchema().parse('deny')).toBe('deny')
      expect(permissionBehaviorSchema().parse('ask')).toBe('ask')
    })

    test('rejects "prompt" (commonly considered alias — must use "ask")', () => {
      // Pin: prompt is NOT a behavior. A regression that accepts it
      // would let invalid settings files load silently.
      expect(() => permissionBehaviorSchema().parse('prompt')).toThrow()
    })

    test('rejects "manual" / "auto" / "" / undefined', () => {
      expect(() => permissionBehaviorSchema().parse('manual')).toThrow()
      expect(() => permissionBehaviorSchema().parse('auto')).toThrow()
      expect(() => permissionBehaviorSchema().parse('')).toThrow()
      expect(() => permissionBehaviorSchema().parse(undefined)).toThrow()
    })

    test('case-sensitive: ALLOW / Allow rejected', () => {
      // Pin: settings file MUST be exact lowercase.
      expect(() => permissionBehaviorSchema().parse('ALLOW')).toThrow()
      expect(() => permissionBehaviorSchema().parse('Allow')).toThrow()
    })
  })

  describe('permissionRuleValueSchema', () => {
    test('toolName required (no toolName → reject)', () => {
      expect(() =>
        permissionRuleValueSchema().parse({ ruleContent: 'x' }),
      ).toThrow()
    })

    test('ruleContent optional (toolName-only rule passes)', () => {
      // Pin: a bare "Bash" rule matches every Bash invocation; this is
      // the common case. ruleContent narrows.
      const result = permissionRuleValueSchema().parse({ toolName: 'Bash' })
      expect(result.toolName).toBe('Bash')
      expect(result.ruleContent).toBeUndefined()
    })

    test('toolName + ruleContent shape (the precise-match form)', () => {
      const result = permissionRuleValueSchema().parse({
        toolName: 'Bash',
        ruleContent: 'ls *',
      })
      expect(result).toEqual({ toolName: 'Bash', ruleContent: 'ls *' })
    })

    test('toolName must be string (number rejected)', () => {
      expect(() =>
        permissionRuleValueSchema().parse({ toolName: 42 }),
      ).toThrow()
    })
  })

  describe('permissionUpdateDestinationSchema', () => {
    test('accepts exactly 5 destinations', () => {
      // Pin: the 5 known scopes. Settings layering hardcodes this.
      const destinations = [
        'userSettings',
        'projectSettings',
        'localSettings',
        'session',
        'cliArg',
      ] as const
      for (const d of destinations) {
        expect(permissionUpdateDestinationSchema().parse(d)).toBe(d)
      }
    })

    test('rejects "global" / "remote" / typos', () => {
      // Pin: "global" is a common typo for "userSettings".
      expect(() =>
        permissionUpdateDestinationSchema().parse('global'),
      ).toThrow()
      expect(() =>
        permissionUpdateDestinationSchema().parse('remote'),
      ).toThrow()
      expect(() =>
        permissionUpdateDestinationSchema().parse('user'),
      ).toThrow()
    })
  })

  describe('permissionUpdateSchema (discriminated union)', () => {
    test('addRules update with behavior + destination', () => {
      const result = permissionUpdateSchema().parse({
        type: 'addRules',
        rules: [{ toolName: 'Bash', ruleContent: 'ls *' }],
        behavior: 'allow',
        destination: 'session',
      })
      expect(result.type).toBe('addRules')
    })

    test('replaceRules accepted', () => {
      const result = permissionUpdateSchema().parse({
        type: 'replaceRules',
        rules: [],
        behavior: 'deny',
        destination: 'projectSettings',
      })
      expect(result.type).toBe('replaceRules')
    })

    test('removeRules accepted', () => {
      const result = permissionUpdateSchema().parse({
        type: 'removeRules',
        rules: [{ toolName: 'Bash' }],
        behavior: 'allow',
        destination: 'userSettings',
      })
      expect(result.type).toBe('removeRules')
    })

    test('setMode update carries `mode` (NOT `behavior`)', () => {
      // Pin: setMode is structurally different — it sets the runtime
      // permission mode (default/plan/acceptEdits/bypassPermissions),
      // not a rule behavior.
      const result = permissionUpdateSchema().parse({
        type: 'setMode',
        mode: 'plan',
        destination: 'session',
      })
      expect(result.type).toBe('setMode')
    })

    test('addDirectories carries `directories` string array', () => {
      const result = permissionUpdateSchema().parse({
        type: 'addDirectories',
        directories: ['/tmp/x', '/tmp/y'],
        destination: 'session',
      })
      expect(result.type).toBe('addDirectories')
    })

    test('removeDirectories carries `directories` string array', () => {
      const result = permissionUpdateSchema().parse({
        type: 'removeDirectories',
        directories: ['/tmp/x'],
        destination: 'projectSettings',
      })
      expect(result.type).toBe('removeDirectories')
    })

    test('unknown `type` rejected (no fallback)', () => {
      expect(() =>
        permissionUpdateSchema().parse({
          type: 'unknownType',
          rules: [],
          behavior: 'allow',
          destination: 'session',
        }),
      ).toThrow()
    })

    test('addRules with wrong destination → rejected', () => {
      expect(() =>
        permissionUpdateSchema().parse({
          type: 'addRules',
          rules: [{ toolName: 'Bash' }],
          behavior: 'allow',
          destination: 'bogusSettings',
        }),
      ).toThrow()
    })

    test('addRules without `behavior` → rejected (required field)', () => {
      expect(() =>
        permissionUpdateSchema().parse({
          type: 'addRules',
          rules: [{ toolName: 'Bash' }],
          destination: 'session',
        }),
      ).toThrow()
    })
  })
})

import { relative } from 'path'
import * as React from 'react'
import { Suspense, use, useMemo } from 'react'
import { Box, NoSelect, Text } from '@anthropic/ink'
import type {
  NotebookCell,
  NotebookCellType,
  NotebookContent,
} from '@thyrox/tool-registry/notebookTypes'
import { intersperse } from '@thyrox/tool-registry/utils/array.js'
import { getCwd } from '@thyrox/app-host/bootstrap/cwd.js'
import { getPatchForDisplay } from '@thyrox/agent/diff.js'
import { getFsImplementation } from '@thyrox/storage/fsOperations.js'
import { safeParseJSON } from '@thyrox/storage/json.js'
import { parseCellId } from '@thyrox/tool-registry/notebook.js'
import { HighlightedCode } from '@thyrox/repl/components/HighlightedCode.js'
import { StructuredDiff } from '@thyrox/repl/components/StructuredDiff.js'
import { StructuredPatchHunk } from 'diff'

type Props = {
  notebook_path: string
  cell_id: string | undefined
  new_source: string
  cell_type?: NotebookCellType
  edit_mode?: string
  verbose: boolean
  width: number
}

type InnerProps = {
  notebook_path: string
  cell_id: string | undefined
  new_source: string
  cell_type?: NotebookCellType
  edit_mode?: string
  verbose: boolean
  width: number
  promise: Promise<NotebookContent | null>
}

export function NotebookEditToolDiff(props: Props): React.ReactNode {
  // Copia de `ccnmt: packages/permission/src/components/
  // NotebookEditPermissionRequest/NotebookEditToolDiff.tsx` con los comentarios
  // traducidos; el cuerpo es el de la fuente.
  //
  // Se construye una promesa que nunca rechaza, para resolver los errores en
  // línea. Memoizada sobre notebook_path, para no releer en cada render.
  const notebookDataPromise = useMemo(
    () =>
      getFsImplementation()
        .readFile(props.notebook_path, { encoding: 'utf-8' })
        .then(content => safeParseJSON(content) as NotebookContent | null)
        .catch(() => null),
    [props.notebook_path],
  )

  return (
    <Suspense fallback={null}>
      <NotebookEditToolDiffInner {...props} promise={notebookDataPromise} />
    </Suspense>
  )
}

function NotebookEditToolDiffInner({
  notebook_path,
  cell_id,
  new_source,
  cell_type,
  edit_mode = 'replace',
  verbose,
  width,
  promise,
}: InnerProps): React.ReactNode {
  const notebookData = use(promise)

  const oldSource = useMemo(() => {
    if (!notebookData || !cell_id) {
      return ''
    }
    const cellIndex = parseCellId(cell_id)
    if (cellIndex !== undefined) {
      if (notebookData.cells[cellIndex]) {
        const source = notebookData.cells[cellIndex].source
        return Array.isArray(source) ? source.join('') : source
      }
      return ''
    }
    const cell = notebookData.cells.find((cell: NotebookCell) => cell.id === cell_id)
    if (!cell) {
      return ''
    }
    return Array.isArray(cell.source) ? cell.source.join('') : cell.source
  }, [notebookData, cell_id])

  const hunks = useMemo(() => {
    if (!notebookData || edit_mode === 'insert' || edit_mode === 'delete') {
      return null
    }
    // Se construye un contenido de archivo "falso" solo con el fuente de la
    // celda. Así se puede usar el mecanismo de diff normal.
    return getPatchForDisplay({
      filePath: notebook_path,
      fileContents: oldSource,
      edits: [
        {
          old_string: oldSource,
          new_string: new_source,
          replace_all: false,
        },
      ],
      ignoreWhitespace: false,
    })
  }, [notebookData, notebook_path, oldSource, new_source, edit_mode])

  let editTypeDescription: string
  switch (edit_mode) {
    case 'insert':
      editTypeDescription = 'Insert new cell'
      break
    case 'delete':
      editTypeDescription = 'Delete cell'
      break
    default:
      editTypeDescription = 'Replace cell contents'
  }

  return (
    <Box flexDirection="column">
      <Box borderStyle="round" flexDirection="column" paddingX={1}>
        <Box paddingBottom={1} flexDirection="column">
          <Text bold>
            {verbose ? notebook_path : relative(getCwd(), notebook_path)}
          </Text>
          <Text dimColor>
            {editTypeDescription} for cell {cell_id}
            {cell_type ? ` (${cell_type})` : ''}
          </Text>
        </Box>
        {edit_mode === 'delete' ? (
          <Box flexDirection="column" paddingLeft={2}>
            <HighlightedCode code={oldSource} filePath={notebook_path} />
          </Box>
        ) : edit_mode === 'insert' ? (
          <Box flexDirection="column" paddingLeft={2}>
            <HighlightedCode
              code={new_source}
              filePath={cell_type === 'markdown' ? 'file.md' : notebook_path}
            />
          </Box>
        ) : hunks ? (
          intersperse(
            hunks.map((_: StructuredPatchHunk) => (
              <StructuredDiff
                key={_.newStart}
                patch={_}
                dim={false}
                width={width}
                filePath={notebook_path}
                firstLine={new_source.split('\n')[0] ?? null}
                fileContent={oldSource}
              />
            )),
            i => (
              <NoSelect fromLeftEdge key={`ellipsis-${i}`}>
                <Text dimColor>...</Text>
              </NoSelect>
            ),
          )
        ) : (
          <HighlightedCode
            code={new_source}
            filePath={cell_type === 'markdown' ? 'file.md' : notebook_path}
          />
        )}
      </Box>
    </Box>
  )
}

// Centralized analytics/telemetry logging for tool permission decisions.
// All permission approve/reject events flow through logPermissionDecision(),
// which fans out to Statsig analytics, OTel telemetry, and code-edit metrics.
import { feature } from 'bun:bundle'
import {
  type AnalyticsMetadata_I_VERIFIED_THIS_IS_NOT_CODE_OR_FILEPATHS,
  logEvent,
} from '@thyrox/local-observability'
import { sanitizeToolNameForAnalytics } from '@thyrox/agent/eventMetadata.js'
import { getCodeEditToolDecisionCounter } from '@thyrox/app-host/bootstrap/state.js'
import type { Tool as ToolType, ToolUseContext } from '@thyrox/tool-registry/Tool.js'
import { getLanguageName } from '@thyrox/output/utils/cliHighlight.js'
import { SandboxManager } from '@thyrox/shell/sandbox.js'
import { logOTelEvent } from '@thyrox/local-observability/telemetryEvents.js'
import type {
  PermissionApprovalSource,
  PermissionRejectionSource,
} from './permissionSourceTypes.js'

type PermissionLogContext = {
  tool: ToolType
  input: unknown
  toolUseContext: ToolUseContext
  messageId: string
  toolUseID: string
}

// Discriminated union: 'accept' pairs with approval sources, 'reject' with rejection sources
type PermissionDecisionArgs =
  | { decision: 'accept'; source: PermissionApprovalSource | 'config' }
  | { decision: 'reject'; source: PermissionRejectionSource | 'config' }

const CODE_EDITING_TOOLS = ['Edit', 'Write', 'NotebookEdit']

function isCodeEditingTool(toolName: string): boolean {
  return CODE_EDITING_TOOLS.includes(toolName)
}

// Builds OTel counter attributes for code editing tools, enriching with
// language when the tool's target file path can be extracted from input
async function buildCodeEditToolAttributes(
  tool: ToolType,
  input: unknown,
  decision: 'accept' | 'reject',
  source: string,
): Promise<Record<string, string>> {
  // Derive language from file path if the tool exposes one (e.g., Edit, Write)
  let language: string | undefined
  if (tool.getPath && input) {
    const parseResult = tool.inputSchema.safeParse(input)
    if (parseResult.success) {
      const filePath = tool.getPath(parseResult.data)
      if (filePath) {
        language = await getLanguageName(filePath)
      }
    }
  }

  return {
    decision,
    source,
    tool_name: tool.name,
    ...(language && { language }),
  }
}

// Flattens structured source into a string label for analytics/OTel events
function sourceToString(
  source: PermissionApprovalSource | PermissionRejectionSource,
): string {
  if (
    (feature('BASH_CLASSIFIER') || feature('TRANSCRIPT_CLASSIFIER')) &&
    source.type === 'classifier'
  ) {
    return 'classifier'
  }
  switch (source.type) {
    case 'hook':
      return 'hook'
    case 'user':
      return source.permanent ? 'user_permanent' : 'user_temporary'
    case 'user_abort':
      return 'user_abort'
    case 'user_reject':
      return 'user_reject'
    default:
      return 'unknown'
  }
}

function baseMetadata(
  messageId: string,
  toolName: string,
  waitMs: number | undefined,
): { [key: string]: boolean | number | undefined } {
  return {
    messageID:
      messageId as AnalyticsMetadata_I_VERIFIED_THIS_IS_NOT_CODE_OR_FILEPATHS,
    toolName:
      sanitizeToolNameForAnalytics(toolName) as AnalyticsMetadata_I_VERIFIED_THIS_IS_NOT_CODE_OR_FILEPATHS,
    sandboxEnabled: SandboxManager.isSandboxingEnabled(),
    // Only include wait time when the user was actually prompted (not auto-approved)
    ...(waitMs !== undefined && { waiting_for_user_permission_ms: waitMs }),
  }
}

// Emits a distinct analytics event name per approval source for funnel analysis
function logApprovalEvent(
  tool: ToolType,
  messageId: string,
  source: PermissionApprovalSource | 'config',
  waitMs: number | undefined,
): void {
  if (source === 'config') {
    // Auto-approved by allowlist in settings -- no user wait time
    logEvent(
      'tengu_tool_use_granted_in_config',
      baseMetadata(messageId, tool.name, undefined),
    )
    return
  }
  if (
    (feature('BASH_CLASSIFIER') || feature('TRANSCRIPT_CLASSIFIER')) &&
    source.type === 'classifier'
  ) {
    logEvent(
      'tengu_tool_use_granted_by_classifier',
      baseMetadata(messageId, tool.name, waitMs),
    )
    return
  }
  switch (source.type) {
    case 'user':
      logEvent(
        source.permanent
          ? 'tengu_tool_use_granted_in_prompt_permanent'
          : 'tengu_tool_use_granted_in_prompt_temporary',
        baseMetadata(messageId, tool.name, waitMs),
      )
      break
    case 'hook':
      logEvent('tengu_tool_use_granted_by_permission_hook', {
        ...baseMetadata(messageId, tool.name, waitMs),
        permanent: source.permanent ?? false,
      })
      break
    default:
      break
  }
}

// Rejections share a single event name, differentiated by metadata fields
function logRejectionEvent(
  tool: ToolType,
  messageId: string,
  source: PermissionRejectionSource | 'config',
  waitMs: number | undefined,
): void {
  if (source === 'config') {
    // Denied by denylist in settings
    logEvent(
      'tengu_tool_use_denied_in_config',
      baseMetadata(messageId, tool.name, undefined),
    )
    return
  }
  logEvent('tengu_tool_use_rejected_in_prompt', {
    ...baseMetadata(messageId, tool.name, waitMs),
    // Distinguish hook rejections from user rejections via separate fields
    ...(source.type === 'hook'
      ? { isHook: true }
      : {
          hasFeedback:
            source.type === 'user_reject' ? source.hasFeedback : false,
        }),
  })
}

// Single entry point for all permission decision logging. Called by permission
// handlers after every approve/reject. Fans out to: analytics events, OTel
// telemetry, code-edit OTel counters, and toolUseContext decision storage.
function logPermissionDecision(
  ctx: PermissionLogContext,
  args: PermissionDecisionArgs,
  permissionPromptStartTimeMs?: number,
): void {
  const { tool, input, toolUseContext, messageId, toolUseID } = ctx
  const { decision, source } = args

  const waiting_for_user_permission_ms =
    permissionPromptStartTimeMs !== undefined
      ? Date.now() - permissionPromptStartTimeMs
      : undefined

  // Log the analytics event
  if (args.decision === 'accept') {
    logApprovalEvent(
      tool,
      messageId,
      args.source,
      waiting_for_user_permission_ms,
    )
  } else {
    logRejectionEvent(
      tool,
      messageId,
      args.source,
      waiting_for_user_permission_ms,
    )
  }

  const sourceString = source === 'config' ? 'config' : sourceToString(source)

  // Track code editing tool metrics
  if (isCodeEditingTool(tool.name)) {
    void buildCodeEditToolAttributes(tool, input, decision, sourceString).then(
      attributes => getCodeEditToolDecisionCounter()?.add(1, attributes),
    )
  }

  // Persist decision on the context so downstream code can inspect what happened
  if (!toolUseContext.toolDecisions) {
    toolUseContext.toolDecisions = new Map()
  }
  toolUseContext.toolDecisions.set(toolUseID, {
    source: sourceString,
    decision,
    timestamp: Date.now(),
  })

  void logOTelEvent('tool_decision', {
    decision,
    source: sourceString,
    tool_name: sanitizeToolNameForAnalytics(tool.name),
    tool_use_id: toolUseID, // ant 3144.js: required for span-correlation
  })
}

export { isCodeEditingTool, buildCodeEditToolAttributes, logPermissionDecision }
export type { PermissionLogContext, PermissionDecisionArgs }

/**
 * Plan mode: el modo en que el agente diseña antes de tocar nada.
 *
 * Porte de la tercera superficie que el binario llama «plan». No es el tablero
 * de tareas ni el `Plan` de una herramienta: es un **modo de sesión** en el que
 * el agente explora, escribe su plan a UN archivo, y pide aprobación.
 *
 * Fuente del porte — el contrato lo fijan los esquemas de las dos herramientas
 * del binario 2.1.261, que son evidencia más fuerte que un identificador
 * minificado:
 *
 * - `EnterPlanMode` no recibe parámetros y **exige aprobación del usuario**.
 * - En el modo, el archivo de plan es *«the only file you can edit»*.
 * - `ExitPlanMode` **no recibe el contenido**: lo lee del archivo. Sólo señala
 *   que el plan está listo para revisión.
 * - La ruta se inyecta en el mensaje de sistema; por defecto
 *   `~/.claude/plans/`, o relativa a la raíz del proyecto si se configura.
 * - El mensaje ramifica: si el archivo existe, se lee y se edita de forma
 *   incremental; si no, se crea.
 *
 * Lo que este porte NO reproduce, y se declara en vez de inventarse: el
 * análisis que originó la tarea afirmaba **cuatro fases declaradas**. En el
 * ejecutable de esta sesión no se pudo confirmar ese conjunto — sí los tres
 * renderers (`agentId` → subagente, `sparse`, `full`) y los estados
 * `planMode*`. Se implementan los estados que el contrato exige, no cuatro
 * fases sin medir.
 *
 * *Métrica:* esquemas de `EnterPlanMode`/`ExitPlanMode` y literales
 * `planFilePath` / `planModeInstructions` / `sparse`-`full` del binario 2.1.261.
 * *Ciega a:* cómo el cliente **presenta** el diálogo de aprobación, que es de
 * su interfaz y no del contrato; y a si existe un conjunto de fases más rico
 * que el binario no expone como literal.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { isAbsolute, join, resolve } from 'node:path'

/**
 * Los estados que el contrato exige, y sólo ésos.
 *
 * `awaitingApproval` es distinto de `planning` porque `ExitPlanMode` no
 * termina el modo: lo deja esperando al usuario. Colapsarlos haría que el
 * agente pudiera escribir en cuanto llama a la herramienta, que es exactamente
 * lo que el modo impide.
 */
export type PlanState = 'inactive' | 'planning' | 'awaitingApproval'

/** Las tres variantes de render que el binario distingue. */
export type PlanVariant = 'subagent' | 'sparse' | 'full'

export type PlanBackendOptions = {
  /** Raíz del proyecto; una `plansDir` relativa se resuelve contra ella. */
  projectRoot: string
  /** Dónde viven los archivos de plan. Sin ella, `~/.claude/plans/`. */
  plansDir?: string
}

/**
 * Resuelve dónde vive el archivo de plan de una sesión.
 *
 * Devuelve la ruta; **no** crea el archivo. Que exista o no es justo lo que
 * ramifica el mensaje de sistema, así que crearlo aquí borraría la distinción.
 */
export function planFilePath(sessionId: string, options: PlanBackendOptions): string {
  const configured = options.plansDir
  const dir = configured
    ? (isAbsolute(configured) ? configured : resolve(options.projectRoot, configured))
    : join(homedir(), '.claude', 'plans')
  return join(dir, `${sessionId}.md`)
}

/**
 * El mensaje de sistema del modo, con su ramificación por existencia.
 *
 * Se porta la estructura, no el texto literal del binario: el texto es suyo y
 * este harness escribe en español (`redaccion-tecnica-es.md`). Lo que sí se
 * porta verbatim es **qué afirma**: prohibición de escribir, el archivo como
 * única excepción, y la obligación de cerrar con la herramienta de salida.
 */
export function planModeInstructions(path: string, extraWritablePath?: string): string {
  const alsoWritable = extraWritablePath
    ? `, además del documento de taller de la sesión (${extraWritablePath})`
    : ''
  const branch = existsSync(path)
    ? `Ya existe un archivo de plan en ${path}. Puedes leerlo y editarlo de forma incremental.`
    : `Todavía no existe archivo de plan. Crea el tuyo en ${path}.`
  return [
    'Plan mode está activo. El usuario indicó que todavía NO quieres que ejecutes:',
    'no hagas ediciones ni ejecutes herramientas que no sean de sólo lectura.',
    `La única excepción es el archivo de plan (${path})${alsoWritable}.`,
    branch,
    'Cuando el plan esté listo, llama a ExitPlanMode para indicar que terminaste.',
  ].join(' ')
}

/**
 * Render del plan en la variante que corresponda.
 *
 * `subagent` va sin encabezado —el padre ya lo enmarca—, `sparse` recorta a las
 * líneas con contenido, y `full` entrega el texto tal cual.
 */
export function renderPlan(text: string, variant: PlanVariant): string {
  if (variant === 'subagent') return text.trim()
  if (variant === 'sparse') {
    return text.split('\n').filter((l) => l.trim() !== '').join('\n')
  }
  return text
}

/** La variante que toca, derivada del contexto — no elegida a mano. */
export function planVariantFor(options: { agentId?: string; sparse?: boolean }): PlanVariant {
  if (options.agentId) return 'subagent'
  return options.sparse ? 'sparse' : 'full'
}

/**
 * El modo vivo de una sesión: su estado, su archivo, y la puerta que impone.
 *
 * No persiste el estado: vive lo que vive la sesión. Lo durable es el archivo,
 * que es justamente lo que sobrevive a un reinicio y lo que `ExitPlanMode` lee.
 */
export class PlanMode {
  private state: PlanState = 'inactive'
  readonly path: string

  constructor(sessionId: string, options: PlanBackendOptions) {
    this.path = planFilePath(sessionId, options)
  }

  current(): PlanState {
    return this.state
  }

  active(): boolean {
    return this.state !== 'inactive'
  }

  /** Entra al modo. Idempotente: entrar dos veces no reinicia nada. */
  enter(): PlanState {
    if (this.state === 'inactive') this.state = 'planning'
    return this.state
  }

  /**
   * Señala que el plan está listo. NO sale del modo.
   *
   * Rehúsa si el archivo no existe o está vacío: `ExitPlanMode` lee del
   * archivo, así que sin contenido la señal no tiene qué presentar y el
   * usuario aprobaría un plan vacío.
   */
  requestApproval(): { ok: boolean; reason?: string; plan?: string } {
    if (this.state === 'inactive') {
      return { ok: false, reason: 'plan mode no está activo' }
    }
    if (!existsSync(this.path)) {
      return { ok: false, reason: `no existe el archivo de plan (${this.path}); escríbelo antes de salir` }
    }
    const plan = readFileSync(this.path, 'utf8')
    if (plan.trim() === '') {
      return { ok: false, reason: `el archivo de plan (${this.path}) está vacío` }
    }
    this.state = 'awaitingApproval'
    return { ok: true, plan }
  }

  /** El usuario aprobó: el modo termina y la escritura vuelve a estar abierta. */
  approve(): PlanState {
    this.state = 'inactive'
    return this.state
  }

  /** El usuario rechazó: vuelve a planificar, no a ejecutar. */
  reject(): PlanState {
    if (this.state === 'awaitingApproval') this.state = 'planning'
    return this.state
  }

  /** Crea el directorio del plan y escribe. Sólo para uso del propio modo. */
  write(text: string): void {
    mkdirSync(join(this.path, '..'), { recursive: true })
    writeFileSync(this.path, text)
  }
}

/**
 * La cuarta capa de la puerta: qué deja pasar el modo.
 *
 * Devuelve `undefined` cuando el modo no opina —y entonces decide la puerta
 * normal— y un veredicto con **su regla nombrada** cuando deniega. Un `deny`
 * anónimo es inexplicable para quien lo recibe, que es el criterio que
 * `permission.ts` ya fija para sus tres capas.
 */
export function planModeVerdict(
  mode: PlanMode | undefined,
  capability: 'read' | 'write' | 'execute',
  target: string,
): { decision: 'deny'; rule: string; reason: string } | undefined {
  if (!mode?.active()) return undefined
  if (capability === 'read') return undefined
  if (capability === 'write' && target !== '' && resolve(target) === resolve(mode.path)) {
    return undefined
  }
  return {
    decision: 'deny',
    rule: 'planMode',
    reason: capability === 'write'
      ? `plan mode: el archivo de plan (${mode.path}) es el único editable`
      : 'plan mode: sólo herramientas de sólo lectura hasta que el plan se apruebe',
  }
}

