function getNonstreamingFallbackTimeoutMs(): number {
  const override = parseInt(readEnv('API_TIMEOUT_MS') || '', 10)
  if (override) return override
  return isEnvTruthy(readEnv('CLAUDE_CODE_REMOTE')) ? 120_000 : 300_000
