import type { BetaRawMessageStreamEvent } from '@anthropic-ai/sdk/resources/beta/messages/messages.mjs'
import { randomUUID } from 'crypto'
import type { GeminiPart, GeminiStreamChunk } from './types.js'

export async function* adaptGeminiStreamToAnthropic(
  stream: AsyncIterable<GeminiStreamChunk>,
  model: string,
): AsyncGenerator<BetaRawMessageStreamEvent, void> {
  const messageId = `msg_${randomUUID().replace(/-/g, '').slice(0, 24)}`
  let started = false
  let stopped = false
  let nextContentIndex = 0
  let openTextLikeBlock:
    | { index: number; type: 'text' | 'thinking' }
    | null = null
  let sawToolUse = false
  let finishReason: string | undefined
  let inputTokens = 0
  let outputTokens = 0

  for await (const chunk of stream) {
    const usage = chunk.usageMetadata
    if (usage) {
      inputTokens = usage.promptTokenCount ?? inputTokens
      outputTokens =
        (usage.candidatesTokenCount ?? 0) + (usage.thoughtsTokenCount ?? 0)
    }

    if (!started) {
      started = true
      yield {
        type: 'message_start',
        message: {
          id: messageId,
          type: 'message',
          role: 'assistant',
          content: [],
          model,
          container: null,
          context_management: null,
          diagnostics: null,
          stop_details: null,
          stop_reason: null,
          stop_sequence: null,
          usage: {
            input_tokens: inputTokens,
            output_tokens: 0,
            cache_creation_input_tokens: 0,
            cache_read_input_tokens: 0,
          },
        },
      } as BetaRawMessageStreamEvent
    }

    const candidate = chunk.candidates?.[0]
    const parts = candidate?.content?.parts ?? []

    for (const part of parts) {
      if (part.functionCall) {
        if (openTextLikeBlock) {
          yield {
            type: 'content_block_stop',
            index: openTextLikeBlock.index,
          } as BetaRawMessageStreamEvent
          openTextLikeBlock = null
        }

        sawToolUse = true
        const toolIndex = nextContentIndex++
        const toolId = `toolu_${randomUUID().replace(/-/g, '').slice(0, 24)}`
        yield {
          type: 'content_block_start',
          index: toolIndex,
          content_block: {
            type: 'tool_use',
            id: toolId,
            name: part.functionCall.name || '',
            input: {},
          },
        } as BetaRawMessageStreamEvent

        if (part.thoughtSignature) {
          yield {
            type: 'content_block_delta',
            index: toolIndex,
            delta: {
              type: 'signature_delta',
              signature: part.thoughtSignature,
            },
          } as BetaRawMessageStreamEvent
        }

        if (part.functionCall.args && Object.keys(part.functionCall.args).length > 0) {
          yield {
            type: 'content_block_delta',
            index: toolIndex,
            delta: {
              type: 'input_json_delta',
              partial_json: JSON.stringify(part.functionCall.args),
            },
          } as BetaRawMessageStreamEvent
        }

        yield {
          type: 'content_block_stop',
          index: toolIndex,
        } as BetaRawMessageStreamEvent
        continue
      }

      const textLikeType = getTextLikeBlockType(part)
      if (textLikeType) {
        if (!openTextLikeBlock || openTextLikeBlock.type !== textLikeType) {
          if (openTextLikeBlock) {
            yield {
              type: 'content_block_stop',
              index: openTextLikeBlock.index,
            } as BetaRawMessageStreamEvent
          }

          openTextLikeBlock = {
            index: nextContentIndex++,
            type: textLikeType,
          }

          yield {
            type: 'content_block_start',
            index: openTextLikeBlock.index,
            content_block:
              textLikeType === 'thinking'
                ? {
                    type: 'thinking',
                    thinking: '',
                    signature: '',
                  }
                : {
                    type: 'text',
                    text: '',
                  },
          } as BetaRawMessageStreamEvent
        }

        if (part.text) {
          yield {
            type: 'content_block_delta',
            index: openTextLikeBlock.index,
            delta:
              textLikeType === 'thinking'
                ? {
                    type: 'thinking_delta',
                    thinking: part.text,
                  }
                : {
                    type: 'text_delta',
                    text: part.text,
                  },
          } as BetaRawMessageStreamEvent
        }

        if (part.thoughtSignature) {
          yield {
            type: 'content_block_delta',
            index: openTextLikeBlock.index,
            delta: {
              type: 'signature_delta',
              signature: part.thoughtSignature,
            },
          } as BetaRawMessageStreamEvent
        }

        continue
      }

      if (part.thoughtSignature && openTextLikeBlock) {
        yield {
          type: 'content_block_delta',
          index: openTextLikeBlock.index,
          delta: {
            type: 'signature_delta',
            signature: part.thoughtSignature,
          },
        } as BetaRawMessageStreamEvent
      }
    }

    if (candidate?.finishReason) {
      finishReason = candidate.finishReason
    }
  }

  if (!started) {
    return
  }

  if (openTextLikeBlock) {
    yield {
      type: 'content_block_stop',
      index: openTextLikeBlock.index,
    } as BetaRawMessageStreamEvent
  }

  if (!stopped) {
    yield {
      type: 'message_delta',
      delta: {
        stop_reason: mapGeminiFinishReason(finishReason, sawToolUse),
        stop_sequence: null,
      },
      usage: {
        output_tokens: outputTokens,
      },
    } as BetaRawMessageStreamEvent

    yield {
      type: 'message_stop',
    } as BetaRawMessageStreamEvent
    stopped = true
  }
}

function getTextLikeBlockType(
  part: GeminiPart,
): 'text' | 'thinking' | null {
  if (typeof part.text !== 'string') {
    return null
  }
  return part.thought ? 'thinking' : 'text'
}

function mapGeminiFinishReason(
  reason: string | undefined,
  sawToolUse: boolean,
): string {
  switch (reason) {
    case 'MAX_TOKENS':
      return 'max_tokens'
    case 'STOP':
    case 'FINISH_REASON_UNSPECIFIED':
    case 'SAFETY':
    case 'RECITATION':
    case 'BLOCKLIST':
    case 'PROHIBITED_CONTENT':
    case 'SPII':
    case 'MALFORMED_FUNCTION_CALL':
    default:
      return sawToolUse ? 'tool_use' : 'end_turn'
  }
}

/**
 * Media block auto-strip retry helper.
 *
 * Ant v2.1.142 broadened the old image-dimension retry into a media-block
 * retry: when the API rejects a specific image/document block, replace that
 * block with a text placeholder and retry the outgoing request copy. This file
 * keeps the historical name for import compatibility, but the implementation is
 * media-aware.
 */
import type Anthropic from '@anthropic-ai/sdk'
import { APIError } from '@anthropic-ai/sdk'

type MediaKind = 'image' | 'document'

export type MediaBlockStripTarget = {
  messageIdx?: number
  contentIdx?: number
  kind: MediaKind
  pixelLimit?: number
}

function isMediaKind(value: string): value is MediaKind {
  return value === 'image' || value === 'document'
}

function mediaPlaceholder(kind: MediaKind, detail?: string): Anthropic.TextBlockParam {
  const label = kind === 'image' ? 'Image' : 'Document'
  return {
    type: 'text',
    text: `[${label} removed: the API could not process this ${kind}${detail ? ` (${detail})` : ''}. Re-read the original file if you need its contents.]`,
  }
}

/**
 * Back-compat export for older callers/tests. Returns targeted coordinates only
 * for image-dimension errors.
 */
export function parseImageDimensionExceededError(
  err: unknown,
):
  | { messageIdx: number; contentIdx: number; pixelLimit?: number }
  | undefined {
  const target = parseMediaBlockStripError(err)
  if (
    target?.kind !== 'image' ||
    target.messageIdx === undefined ||
    target.contentIdx === undefined
  ) {
    return undefined
  }
  return {
    messageIdx: target.messageIdx,
    contentIdx: target.contentIdx,
    pixelLimit: target.pixelLimit,
  }
}

/**
 * Parse API 400s that point at a media block. Supports both precise paths like
 * `messages.3.content.1.document` and broader media errors where the API omits
 * coordinates.
 */
export function parseMediaBlockStripError(
  err: unknown,
): MediaBlockStripTarget | undefined {
  if (!(err instanceof APIError) || err.status !== 400) {
    return undefined
  }
  const msg = err.message ?? ''
  const lower = msg.toLowerCase()

  const coordMatch =
    /messages[.[](\d+)[\].]+content[.[](\d+)[\].]+(?:tool_result[.[]content[.[]\d+[\].]+)?(image|document|pdf)/.exec(
      msg,
    )
  if (coordMatch && isMediaErrorMessage(msg)) {
    const rawKind = coordMatch[3] === 'image' ? 'image' : 'document'
    return {
      messageIdx: Number(coordMatch[1]),
      contentIdx: Number(coordMatch[2]),
      kind: rawKind,
      pixelLimit: extractPixelLimit(msg),
    }
  }

  if (msg.includes('request_too_large') || lower.includes('too much media')) {
    return { kind: 'document' }
  }
  if (
    lower.includes('image dimensions exceed') ||
    lower.includes('image exceeds') ||
    lower.includes('invalid image')
  ) {
    return { kind: 'image', pixelLimit: extractPixelLimit(msg) }
  }
  if (
    lower.includes('pdf') ||
    lower.includes('document') ||
    lower.includes('maximum of')
  ) {
    return { kind: 'document' }
  }
  return undefined
}

function isMediaErrorMessage(msg: string): boolean {
  const lower = msg.toLowerCase()
  return (
    msg.includes('request_too_large') ||
    lower.includes('too much media') ||
    msg.includes('dimensions exceed max allowed size') ||
    lower.includes('image exceeds') ||
    lower.includes('invalid image') ||
    lower.includes('pdf') ||
    lower.includes('document')
  )
}

function extractPixelLimit(msg: string): number | undefined {
  const dimMatch = /dimensions exceed max allowed size.*?(\d+) pixels/.exec(msg)
  return dimMatch ? Number(dimMatch[1]) : undefined
}

/**
 * Back-compat export for older callers/tests.
 */
export function stripOversizedImageFromMessages(
  messages: readonly Anthropic.MessageParam[],
  coords: { messageIdx: number; contentIdx: number },
): readonly Anthropic.MessageParam[] {
  return stripTargetedMediaBlockFromMessages(messages, {
    ...coords,
    kind: 'image',
  })
}

export function stripMediaBlockFromMessages(
  messages: readonly Anthropic.MessageParam[],
  target: MediaBlockStripTarget,
): readonly Anthropic.MessageParam[] {
  if (target.messageIdx !== undefined && target.contentIdx !== undefined) {
    const targeted = stripTargetedMediaBlockFromMessages(messages, {
      messageIdx: target.messageIdx,
      contentIdx: target.contentIdx,
      kind: target.kind,
    })
    if (targeted !== messages) return targeted
  }
  return stripLatestMediaBlockFromMessages(messages, target.kind)
}

function stripTargetedMediaBlockFromMessages(
  messages: readonly Anthropic.MessageParam[],
  target: Required<Pick<MediaBlockStripTarget, 'messageIdx' | 'contentIdx'>> &
    Pick<MediaBlockStripTarget, 'kind'>,
): readonly Anthropic.MessageParam[] {
  const { messageIdx, contentIdx, kind } = target
  const msg = messages[messageIdx]
  if (!msg || msg.role !== 'user' || !Array.isArray(msg.content)) {
    return messages
  }
  const block = msg.content[contentIdx]
  if (!block || block.type !== kind) {
    return messages
  }
  const newContent = msg.content.map((item, idx) =>
    idx === contentIdx ? mediaPlaceholder(kind) : item,
  )
  const newMsg: Anthropic.MessageParam = {
    ...msg,
    content: newContent,
  }
  return messages.map((m, idx) => (idx === messageIdx ? newMsg : m))
}

function stripLatestMediaBlockFromMessages(
  messages: readonly Anthropic.MessageParam[],
  kind: MediaKind,
): readonly Anthropic.MessageParam[] {
  for (let messageIdx = messages.length - 1; messageIdx >= 0; messageIdx--) {
    const msg = messages[messageIdx]
    if (!msg || msg.role !== 'user' || !Array.isArray(msg.content)) continue
    for (let contentIdx = msg.content.length - 1; contentIdx >= 0; contentIdx--) {
      const block = msg.content[contentIdx]
      if (block && isMediaKind(block.type) && block.type === kind) {
        return stripTargetedMediaBlockFromMessages(messages, {
          messageIdx,
          contentIdx,
          kind,
        })
      }
    }
  }
  return messages
}

/**
 * Model deprecation utilities
 *
 * Contains information about deprecated models and their retirement dates.
 */

import { type APIProvider, getAPIProvider } from '../providers.js'

type DeprecatedModelInfo = {
  isDeprecated: true
  modelName: string
  retirementDate: string
}

type NotDeprecatedInfo = {
  isDeprecated: false
}

type DeprecationInfo = DeprecatedModelInfo | NotDeprecatedInfo

type DeprecationEntry = {
  /** Human-readable model name */
  modelName: string
  /** Retirement dates by provider (null = not deprecated for that provider) */
  retirementDates: Record<APIProvider, string | null>
}

/**
 * Deprecated models and their retirement dates by provider.
 * Keys are substrings to match in model IDs (case-insensitive).
 * To add a new deprecated model, add an entry to this object.
 */
const DEPRECATED_MODELS: Record<string, DeprecationEntry> = {
  'claude-3-opus': {
    modelName: 'Claude 3 Opus',
    retirementDates: {
      firstParty: 'January 5, 2026',
      bedrock: 'January 15, 2026',
      vertex: 'January 5, 2026',
      foundry: 'January 5, 2026',
      codex: null,
      gemini: null,
      openai: null,
    },
  },
  'claude-3-7-sonnet': {
    modelName: 'Claude 3.7 Sonnet',
    retirementDates: {
      firstParty: 'February 19, 2026',
      bedrock: 'April 28, 2026',
      vertex: 'May 11, 2026',
      foundry: 'February 19, 2026',
      codex: null,
      gemini: null,
      openai: null,
    },
  },
  'claude-3-5-haiku': {
    modelName: 'Claude 3.5 Haiku',
    retirementDates: {
      firstParty: 'February 19, 2026',
      bedrock: null,
      vertex: null,
      foundry: null,
      codex: null,
      gemini: null,
      openai: null,
    },
  },
}

/**
 * Check if a model is deprecated and get its deprecation info
 */
function getDeprecatedModelInfo(modelId: string): DeprecationInfo {
  const lowercaseModelId = modelId.toLowerCase()
  const provider = getAPIProvider()

  for (const [key, value] of Object.entries(DEPRECATED_MODELS)) {
    const retirementDate = value.retirementDates[provider]
    if (!lowercaseModelId.includes(key) || !retirementDate) {
      continue
    }
    return {
      isDeprecated: true,
      modelName: value.modelName,
      retirementDate,
    }
  }

  return { isDeprecated: false }
}

/**
 * Get a deprecation warning message for a model, or null if not deprecated
 */
export function getModelDeprecationWarning(
  modelId: string | null,
): string | null {
  if (!modelId) {
    return null
  }

  const info = getDeprecatedModelInfo(modelId)
  if (!info.isDeprecated) {
    return null
  }

  return `⚠ ${info.modelName} will be retired on ${info.retirementDate}. Consider switching to a newer model.`
}

import { describe, expect, it } from 'bun:test'
import { anthropicMessagesToOpenAI } from '../convertMessages.js'

describe('convertMessages — thinking block round-trip', () => {
  it('preserves reasoning_content from thinking blocks on assistant messages', () => {
    const messages = [
      {
        type: 'user' as const,
        uuid: 'u1',
        message: { role: 'user', content: 'hello' },
      },
      {
        type: 'assistant' as const,
        uuid: 'a1',
        message: {
          role: 'assistant',
          content: [
            { type: 'thinking' as const, thinking: 'Let me think...', signature: 'sig123' },
            { type: 'text' as const, text: 'Hi there!' },
          ],
        },
      },
    ]

    const openaiMessages = anthropicMessagesToOpenAI(messages, [])
    const assistantMsg = openaiMessages.find(m => m.role === 'assistant') as any

    expect(assistantMsg).toBeDefined()
    expect(assistantMsg.reasoning_content).toBe('Let me think...')
    expect(assistantMsg.content).toBe('Hi there!')
  })

  it('concatenates multiple thinking blocks into single reasoning_content', () => {
    const messages = [
      {
        type: 'assistant' as const,
        uuid: 'a1',
        message: {
          role: 'assistant',
          content: [
            { type: 'thinking' as const, thinking: 'Part A. ', signature: 'sig1' },
            { type: 'thinking' as const, thinking: 'Part B.', signature: 'sig2' },
            { type: 'text' as const, text: 'Answer' },
          ],
        },
      },
    ]

    const openaiMessages = anthropicMessagesToOpenAI(messages, [])
    const assistantMsg = openaiMessages.find(m => m.role === 'assistant') as any

    expect(assistantMsg.reasoning_content).toBe('Part A. Part B.')
  })

  it('does NOT add reasoning_content when there are no thinking blocks', () => {
    const messages = [
      {
        type: 'assistant' as const,
        uuid: 'a1',
        message: {
          role: 'assistant',
          content: [{ type: 'text' as const, text: 'No thinking here' }],
        },
      },
    ]

    const openaiMessages = anthropicMessagesToOpenAI(messages, [])
    const assistantMsg = openaiMessages.find(m => m.role === 'assistant') as any

    expect(assistantMsg.reasoning_content).toBeUndefined()
    expect(assistantMsg.content).toBe('No thinking here')
  })

  it('includes reasoning_content alongside tool_calls', () => {
    const messages = [
      {
        type: 'assistant' as const,
        uuid: 'a1',
        message: {
          role: 'assistant',
          content: [
            { type: 'thinking' as const, thinking: 'Need to use a tool.', signature: 'sig1' },
            {
              type: 'tool_use' as const,
              id: 'tool_1',
              name: 'bash',
              input: { command: 'ls' },
            },
          ],
        },
      },
    ]

    const openaiMessages = anthropicMessagesToOpenAI(messages, [])
    const assistantMsg = openaiMessages.find(m => m.role === 'assistant') as any

    expect(assistantMsg.reasoning_content).toBe('Need to use a tool.')
    expect(assistantMsg.tool_calls).toHaveLength(1)
    expect(assistantMsg.tool_calls[0].function.name).toBe('bash')
  })
})

/**
 * OpenAI stream adapter — SDK-to-SDK shape translation. Heavy `as any`
 * usage is by-design type-system bypass: OpenAI extensions like
 * `prompt_tokens_details` and `reasoning_content` are runtime fields
 * not in the published `ChatCompletionChunk` types.
 */
import type { BetaRawMessageStreamEvent } from '@anthropic-ai/sdk/resources/beta/messages/messages.mjs'
import type { ChatCompletionChunk } from 'openai/resources/chat/completions/completions.mjs'
import { randomUUID } from 'crypto'

/**
 * Adapt an OpenAI streaming response into Anthropic BetaRawMessageStreamEvent.
 *
 * Mapping:
 *   First chunk              → message_start
 *   delta.reasoning_content  → content_block_start(thinking) + thinking_delta + content_block_stop
 *   delta.content            → content_block_start(text) + text_delta + content_block_stop
 *   delta.tool_calls         → content_block_start(tool_use) + input_json_delta + content_block_stop
 *   finish_reason            → message_delta(stop_reason) + message_stop
 *   usage.cached_tokens      → cache_read_input_tokens in message_start usage
 *
 * Thinking support:
 *   DeepSeek and compatible providers send `delta.reasoning_content` for chain-of-thought.
 *   This is mapped to Anthropic's `thinking` content blocks:
 *     content_block_start: { type: 'thinking', thinking: '', signature: '' }
 *     content_block_delta: { type: 'thinking_delta', thinking: '...' }
 *
 * Prompt caching:
 *   OpenAI reports cached tokens in usage.prompt_tokens_details.cached_tokens.
 *   This is mapped to Anthropic's cache_read_input_tokens.
 */
export async function* adaptOpenAIStreamToAnthropic(
  stream: AsyncIterable<ChatCompletionChunk>,
  model: string,
): AsyncGenerator<BetaRawMessageStreamEvent, void> {
  const messageId = `msg_${randomUUID().replace(/-/g, '').slice(0, 24)}`

  let started = false
  let currentContentIndex = -1

  // Track tool_use blocks: tool_calls index → { contentIndex, id, name, arguments }
  const toolBlocks = new Map<number, { contentIndex: number; id: string; name: string; arguments: string }>()

  // Track thinking block state
  let thinkingBlockOpen = false

  // Track text block state
  let textBlockOpen = false

  // Track usage
  let inputTokens = 0
  let outputTokens = 0
  let cachedTokens = 0

  // Track all open content block indices (for cleanup)
  const openBlockIndices = new Set<number>()

  for await (const chunk of stream) {
    const choice = chunk.choices?.[0]
    const delta = choice?.delta

    // Extract usage from any chunk that carries it
    if (chunk.usage) {
      inputTokens = chunk.usage.prompt_tokens ?? inputTokens
      outputTokens = chunk.usage.completion_tokens ?? outputTokens
      // OpenAI prompt caching: prompt_tokens_details.cached_tokens
      const details = (chunk.usage as any).prompt_tokens_details
      if (details?.cached_tokens) {
        cachedTokens = details.cached_tokens
      }
    }

    // Emit message_start on first chunk
    if (!started) {
      started = true

      yield {
        type: 'message_start',
        message: {
          id: messageId,
          type: 'message',
          role: 'assistant',
          content: [],
          model,
          container: null,
          context_management: null,
          diagnostics: null,
          stop_details: null,
          stop_reason: null,
          stop_sequence: null,
          usage: {
            input_tokens: inputTokens,
            output_tokens: 0,
            cache_creation_input_tokens: 0,
            cache_read_input_tokens: cachedTokens,
          },
        },
      } as BetaRawMessageStreamEvent
    }

    if (!delta) continue

    // Handle reasoning_content → Anthropic thinking block
    // DeepSeek and compatible providers send delta.reasoning_content
    const reasoningContent = (delta as any).reasoning_content
    if (reasoningContent != null && reasoningContent !== '') {
      if (!thinkingBlockOpen) {
        currentContentIndex++
        thinkingBlockOpen = true
        openBlockIndices.add(currentContentIndex)

        yield {
          type: 'content_block_start',
          index: currentContentIndex,
          content_block: {
            type: 'thinking',
            thinking: '',
            signature: '',
          },
        } as BetaRawMessageStreamEvent
      }

      yield {
        type: 'content_block_delta',
        index: currentContentIndex,
        delta: {
          type: 'thinking_delta',
          thinking: reasoningContent,
        },
      } as BetaRawMessageStreamEvent
    }

    // Handle text content
    if (delta.content != null && delta.content !== '') {
      if (!textBlockOpen) {
        // Close thinking block if still open (reasoning done, now generating answer)
        if (thinkingBlockOpen) {
          yield {
            type: 'content_block_stop',
            index: currentContentIndex,
          } as BetaRawMessageStreamEvent
          openBlockIndices.delete(currentContentIndex)
          thinkingBlockOpen = false
        }

        currentContentIndex++
        textBlockOpen = true
        openBlockIndices.add(currentContentIndex)

        yield {
          type: 'content_block_start',
          index: currentContentIndex,
          content_block: {
            type: 'text',
            text: '',
          },
        } as BetaRawMessageStreamEvent
      }

      yield {
        type: 'content_block_delta',
        index: currentContentIndex,
        delta: {
          type: 'text_delta',
          text: delta.content,
        },
      } as BetaRawMessageStreamEvent
    }

    // Handle tool calls
    if (delta.tool_calls) {
      for (const tc of delta.tool_calls) {
        const tcIndex = tc.index

        if (!toolBlocks.has(tcIndex)) {
          // Close thinking block if open
          if (thinkingBlockOpen) {
            yield {
              type: 'content_block_stop',
              index: currentContentIndex,
            } as BetaRawMessageStreamEvent
            openBlockIndices.delete(currentContentIndex)
            thinkingBlockOpen = false
          }

          // Close text block if open
          if (textBlockOpen) {
            yield {
              type: 'content_block_stop',
              index: currentContentIndex,
            } as BetaRawMessageStreamEvent
            openBlockIndices.delete(currentContentIndex)
            textBlockOpen = false
          }

          // Start new tool_use block
          currentContentIndex++
          const toolId = tc.id || `toolu_${randomUUID().replace(/-/g, '').slice(0, 24)}`
          const toolName = tc.function?.name || ''

          toolBlocks.set(tcIndex, {
            contentIndex: currentContentIndex,
            id: toolId,
            name: toolName,
            arguments: '',
          })
          openBlockIndices.add(currentContentIndex)

          yield {
            type: 'content_block_start',
            index: currentContentIndex,
            content_block: {
              type: 'tool_use',
              id: toolId,
              name: toolName,
              input: {},
            },
          } as BetaRawMessageStreamEvent
        }

        // Stream argument fragments
        const argFragment = tc.function?.arguments
        if (argFragment) {
          toolBlocks.get(tcIndex)!.arguments += argFragment
          yield {
            type: 'content_block_delta',
            index: toolBlocks.get(tcIndex)!.contentIndex,
            delta: {
              type: 'input_json_delta',
              partial_json: argFragment,
            },
          } as BetaRawMessageStreamEvent
        }
      }
    }

    // Handle finish
    if (choice?.finish_reason) {
      // Close thinking block if still open
      if (thinkingBlockOpen) {
        yield {
          type: 'content_block_stop',
          index: currentContentIndex,
        } as BetaRawMessageStreamEvent
        openBlockIndices.delete(currentContentIndex)
        thinkingBlockOpen = false
      }

      // Close text block if still open
      if (textBlockOpen) {
        yield {
          type: 'content_block_stop',
          index: currentContentIndex,
        } as BetaRawMessageStreamEvent
        openBlockIndices.delete(currentContentIndex)
        textBlockOpen = false
      }

      // Close all tool blocks that haven't been closed yet
      for (const [, block] of toolBlocks) {
        if (openBlockIndices.has(block.contentIndex)) {
          yield {
            type: 'content_block_stop',
            index: block.contentIndex,
          } as BetaRawMessageStreamEvent
          openBlockIndices.delete(block.contentIndex)
        }
      }

      // Map finish_reason to Anthropic stop_reason.
      // Some backends return "stop" even when tool_calls are present —
      // force "tool_use" when we saw any tool blocks to ensure the query
      // loop actually executes the tools.
      const hasToolCalls = toolBlocks.size > 0
      const stopReason = hasToolCalls ? 'tool_use' : mapFinishReason(choice.finish_reason)

      yield {
        type: 'message_delta',
        delta: {
          stop_reason: stopReason,
          stop_sequence: null,
        },
        usage: {
          output_tokens: outputTokens,
        },
      } as BetaRawMessageStreamEvent

      yield {
        type: 'message_stop',
      } as BetaRawMessageStreamEvent
    }
  }

  // Safety: close any remaining open blocks if stream ended without finish_reason
  for (const idx of openBlockIndices) {
    yield {
      type: 'content_block_stop',
      index: idx,
    } as BetaRawMessageStreamEvent
  }
}

/**
 * Map OpenAI finish_reason to Anthropic stop_reason.
 *
 * stop           → end_turn
 * tool_calls     → tool_use
 * length         → max_tokens
 * content_filter → end_turn
 */
function mapFinishReason(reason: string): string {
  switch (reason) {
    case 'stop':
      return 'end_turn'
    case 'tool_calls':
      return 'tool_use'
    case 'length':
      return 'max_tokens'
    case 'content_filter':
      return 'end_turn'
    default:
      return 'end_turn'
  }
}

import type { BetaToolUnion } from '@anthropic-ai/sdk/resources/beta/messages/messages.mjs'
import { randomUUID } from 'crypto'
import type {
  ProviderAssistantMessage,
  ProviderMessage,
  ProviderSystemAPIErrorMessage,
  ProviderTool,
  ProviderToolPermissionContext,
  ProviderTools,
  ProviderToolSchemaOptions,
} from './contracts.js'
import { readEnv } from '@thyrox/config/env'

export const TOOL_SEARCH_TOOL_NAME = 'ToolSearch'

export function safeParseJSON(input: string): unknown {
  try {
    return JSON.parse(input)
  } catch {
    return null
  }
}

export function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message
  return String(error)
}

export function createAssistantAPIErrorMessage(args: {
  content: string
  apiError?: unknown
  error?: unknown
  errorDetails?: string
}): ProviderAssistantMessage | ProviderSystemAPIErrorMessage {
  const message = {
    role: 'assistant',
    content: [
      {
        type: 'text',
        text: args.content || 'No content',
      },
    ],
  }

  return {
    type: 'assistant',
    uuid: randomUUID(),
    timestamp: new Date().toISOString(),
    isApiErrorMessage: true,
    apiError: args.apiError,
    error: args.error,
    errorDetails: args.errorDetails,
    message,
  } as ProviderAssistantMessage
}

export function normalizeContentFromAPI(
  blocks: unknown,
  _tools: ProviderTools,
  _agentId?: string,
): NonNullable<ProviderMessage['message']>['content'] {
  if (!Array.isArray(blocks)) return []
  return blocks.map(block => {
    if (!block || typeof block !== 'object') return block
    const typed = block as Record<string, unknown>
    if (typed.type === 'tool_use' && typeof typed.input === 'string') {
      return {
        ...typed,
        input: safeParseJSON(typed.input) ?? {},
      }
    }
    if (typed.type === 'server_tool_use' && typeof typed.input === 'string') {
      return {
        ...typed,
        input: safeParseJSON(typed.input) ?? {},
      }
    }
    return typed
  }) as NonNullable<ProviderMessage['message']>['content']
}

export function normalizeMessagesForAPI(
  messages: readonly ProviderMessage[],
  _tools: ProviderTools,
): ProviderMessage[] {
  return messages.filter(
    msg =>
      (msg.type === 'user' || msg.type === 'assistant') &&
      !msg.isVirtual &&
      msg.message &&
      msg.message.content !== undefined,
  )
}

function getToolDescription(
  tool: ProviderTool,
  options: ProviderToolSchemaOptions,
): Promise<string> | string {
  if (typeof tool.prompt === 'function') {
    return tool.prompt({
      getToolPermissionContext:
        options.getToolPermissionContext ??
        (async () =>
          ({
            mode: 'default',
          }) as ProviderToolPermissionContext),
      tools: options.tools,
      agents: options.agents,
      allowedAgentTypes: options.allowedAgentTypes,
    })
  }
  if (typeof tool.description === 'function') {
    return tool.description()
  }
  if (typeof tool.description === 'string') {
    return tool.description
  }
  return ''
}

function getToolInputSchema(tool: ProviderTool): Record<string, unknown> {
  const candidate =
    'inputJSONSchema' in tool
      ? (tool.inputJSONSchema as unknown)
      : undefined
  if (candidate && typeof candidate === 'object' && !Array.isArray(candidate)) {
    return candidate as Record<string, unknown>
  }

  return {
    type: 'object',
    properties: {},
  }
}

export async function toolToAPISchema(
  tool: ProviderTool,
  options: ProviderToolSchemaOptions,
  _signal?: AbortSignal,
): Promise<BetaToolUnion> {
  const schema: Record<string, unknown> = {
    name: tool.name,
    description: await getToolDescription(tool, options),
    input_schema: getToolInputSchema(tool),
  }

  if (options.deferLoading) {
    schema.defer_loading = true
  }
  if (options.cacheControl) {
    schema.cache_control = options.cacheControl
  }

  return schema as BetaToolUnion
}

export function calculateUSDCost(_model: string, _usage: unknown): number {
  return 0
}

export function isDeferredTool(tool: ProviderTool): boolean {
  return tool.isMcp === true || tool.shouldDefer === true
}

export function extractDiscoveredToolNames(
  messages: readonly ProviderMessage[],
): Set<string> {
  const discovered = new Set<string>()
  for (const message of messages) {
    if (message.type !== 'user') continue
    const content = message.message?.content
    if (!Array.isArray(content)) continue
    for (const block of content) {
      if (
        block &&
        typeof block === 'object' &&
        'type' in block &&
        (block as { type: unknown }).type === 'tool_result' &&
        'content' in block &&
        Array.isArray((block as { content: unknown }).content)
      ) {
        for (const item of (block as { content: unknown[] }).content) {
          if (
            item &&
            typeof item === 'object' &&
            'type' in item &&
            (item as { type: unknown }).type === 'tool_reference' &&
            'tool_name' in item &&
            typeof (item as { tool_name: unknown }).tool_name === 'string'
          ) {
            discovered.add((item as { tool_name: string }).tool_name)
          }
        }
      }
    }
  }
  return discovered
}

export async function isToolSearchEnabled(
  _model: string,
  tools: ProviderTools,
  _getToolPermissionContext: () => Promise<ProviderToolPermissionContext>,
  _agents: readonly { [key: string]: unknown }[],
  _querySource?: string,
  _signal?: AbortSignal,
): Promise<boolean> {
  return (
    readEnv('ENABLE_TOOL_SEARCH') !== 'false' &&
    tools.some(tool => tool.name === TOOL_SEARCH_TOOL_NAME)
  )
}

import { describe, expect, test } from 'bun:test'
import {
  expandPastedTextRefs,
  formatImageRef,
  formatPastedTextRef,
  getPastedTextRefNumLines,
  parseReferences,
} from '../history.js'

describe('getPastedTextRefNumLines', () => {
  test('zero for single-line text', () => {
    expect(getPastedTextRefNumLines('hello')).toBe(0)
  })
  test('counts \\n delimiters (not lines)', () => {
    // "line1\nline2\nline3" has 2 newlines, so +2 lines
    expect(getPastedTextRefNumLines('line1\nline2\nline3')).toBe(2)
  })
  test('counts \\r\\n as one delimiter', () => {
    expect(getPastedTextRefNumLines('a\r\nb')).toBe(1)
  })
  test('counts \\r alone', () => {
    expect(getPastedTextRefNumLines('a\rb')).toBe(1)
  })
  test('mixed line endings', () => {
    expect(getPastedTextRefNumLines('a\r\nb\nc\rd')).toBe(3)
  })
})

describe('formatPastedTextRef', () => {
  test('omits +lines suffix for zero', () => {
    expect(formatPastedTextRef(1, 0)).toBe('[Pasted text #1]')
  })
  test('includes +lines suffix when nonzero', () => {
    expect(formatPastedTextRef(7, 42)).toBe('[Pasted text #7 +42 lines]')
  })
})

describe('formatImageRef', () => {
  test('formats numeric id', () => {
    expect(formatImageRef(3)).toBe('[Image #3]')
  })
})

describe('parseReferences', () => {
  test('parses pasted-text reference', () => {
    const refs = parseReferences('hello [Pasted text #5 +10 lines] world')
    expect(refs).toHaveLength(1)
    expect(refs[0]?.id).toBe(5)
    expect(refs[0]?.match).toBe('[Pasted text #5 +10 lines]')
    expect(refs[0]?.index).toBe(6)
  })
  test('parses image reference', () => {
    const refs = parseReferences('see [Image #2] here')
    expect(refs).toHaveLength(1)
    expect(refs[0]?.id).toBe(2)
  })
  test('parses truncated-text reference', () => {
    const refs = parseReferences('start [...Truncated text #9] end')
    expect(refs).toHaveLength(1)
    expect(refs[0]?.id).toBe(9)
  })
  test('finds multiple refs in one input', () => {
    const refs = parseReferences('[Pasted text #1] then [Image #2]')
    expect(refs).toHaveLength(2)
    expect(refs.map(r => r.id)).toEqual([1, 2])
  })
  test('filters id 0 (treated as invalid)', () => {
    const refs = parseReferences('[Pasted text #0] [Image #1]')
    // id=0 is filtered out by the .filter() in parseReferences
    expect(refs.map(r => r.id)).toEqual([1])
  })
  test('returns empty for input with no refs', () => {
    expect(parseReferences('plain text')).toEqual([])
  })
})

describe('expandPastedTextRefs', () => {
  test('inlines text content for matching ref', () => {
    const input = 'hello [Pasted text #1 +2 lines] world'
    const out = expandPastedTextRefs(input, {
      1: { id: 1, type: 'text', content: 'a\nb\nc' },
    })
    expect(out).toBe('hello a\nb\nc world')
  })

  test('leaves image refs alone', () => {
    const input = 'see [Image #1] here'
    const out = expandPastedTextRefs(input, {
      1: { id: 1, type: 'image', content: '', mediaType: 'image/png' },
    })
    expect(out).toBe('see [Image #1] here')
  })

  test('skips refs with missing pastedContents entry', () => {
    const input = 'see [Pasted text #99] here'
    const out = expandPastedTextRefs(input, {})
    expect(out).toBe('see [Pasted text #99] here')
  })

  test('expands multiple refs in correct positions even when contents shift offsets', () => {
    const input = '[Pasted text #1] middle [Pasted text #2 +0 lines]'
    const out = expandPastedTextRefs(input, {
      1: { id: 1, type: 'text', content: 'AAA' },
      2: { id: 2, type: 'text', content: 'BBB' },
    })
    expect(out).toBe('AAA middle BBB')
  })

  test('content containing a placeholder-looking string is not re-parsed', () => {
    // Critical correctness test: content "[Pasted text #99]" inserted via
    // expansion should NOT be treated as a real ref on subsequent calls.
    // (We test the single-call case: the impl uses original-match offsets,
    // so a placeholder-shaped insertion stays inert within one expansion.)
    const input = '[Pasted text #1]'
    const out = expandPastedTextRefs(input, {
      1: { id: 1, type: 'text', content: '[Pasted text #99]' },
    })
    expect(out).toBe('[Pasted text #99]')
  })
})

/**
 * Tests for isHookEqual — pure helper deciding if two hooks are
 * equal. Used by hook deduplication and registration paths.
 *
 * Wrong equality:
 * - duplicate hooks register and fire TWICE (e.g. PostToolUse hook
 *   runs twice per tool call)
 * - distinct hooks merge → one silently drops (user's hook + plugin
 *   hook with same command but different `if` condition)
 *
 * 5 hook types: command (shell command), prompt (text prompt to
 * user), agent (subagent), http (webhook), function (in-process
 * callback — never equal because no stable id).
 */
import { describe, expect, test } from 'bun:test'
import { isHookEqual } from '../isHookEqual.js'

type Hook = Parameters<typeof isHookEqual>[0]

describe('isHookEqual — type discrimination', () => {
  test('command vs prompt → false (different types)', () => {
    expect(
      isHookEqual(
        { type: 'command', command: 'echo hi' } as Hook,
        { type: 'prompt', prompt: 'echo hi' } as Hook,
      ),
    ).toBe(false)
  })

  test('agent vs http → false', () => {
    expect(
      isHookEqual(
        { type: 'agent', prompt: 'do thing' } as Hook,
        { type: 'http', url: 'https://example.com' } as Hook,
      ),
    ).toBe(false)
  })
})

describe('isHookEqual — command type', () => {
  test('same command, default shell, no if → true', () => {
    const a = { type: 'command', command: 'echo hi' } as Hook
    const b = { type: 'command', command: 'echo hi' } as Hook
    expect(isHookEqual(a, b)).toBe(true)
  })

  test('different commands → false', () => {
    expect(
      isHookEqual(
        { type: 'command', command: 'echo a' } as Hook,
        { type: 'command', command: 'echo b' } as Hook,
      ),
    ).toBe(false)
  })

  test('undefined shell vs explicit "bash" → equal (defaults match)', () => {
    // Documented contract: shell defaults to DEFAULT_HOOK_SHELL ('bash');
    // undefined === 'bash' for equality.
    expect(
      isHookEqual(
        { type: 'command', command: 'echo' } as Hook,
        { type: 'command', command: 'echo', shell: 'bash' } as Hook,
      ),
    ).toBe(true)
  })

  test('different shells → false', () => {
    expect(
      isHookEqual(
        { type: 'command', command: 'echo', shell: 'bash' } as Hook,
        { type: 'command', command: 'echo', shell: 'powershell' } as Hook,
      ),
    ).toBe(false)
  })

  test('same command + different `if` → false (if is part of identity)', () => {
    // Documented: if is part of hook identity. Same command with
    // different conditions = distinct hooks.
    expect(
      isHookEqual(
        { type: 'command', command: 'echo', if: 'a' } as Hook,
        { type: 'command', command: 'echo', if: 'b' } as Hook,
      ),
    ).toBe(false)
  })

  test('undefined `if` vs empty string `if` → equal (both default)', () => {
    expect(
      isHookEqual(
        { type: 'command', command: 'echo' } as Hook,
        { type: 'command', command: 'echo', if: '' } as Hook,
      ),
    ).toBe(true)
  })
})

describe('isHookEqual — prompt type', () => {
  test('same prompt → true', () => {
    expect(
      isHookEqual(
        { type: 'prompt', prompt: 'hello' } as Hook,
        { type: 'prompt', prompt: 'hello' } as Hook,
      ),
    ).toBe(true)
  })

  test('different prompts → false', () => {
    expect(
      isHookEqual(
        { type: 'prompt', prompt: 'a' } as Hook,
        { type: 'prompt', prompt: 'b' } as Hook,
      ),
    ).toBe(false)
  })

  test('same prompt different `if` → false', () => {
    expect(
      isHookEqual(
        { type: 'prompt', prompt: 'a', if: 'x' } as Hook,
        { type: 'prompt', prompt: 'a', if: 'y' } as Hook,
      ),
    ).toBe(false)
  })
})

describe('isHookEqual — agent type', () => {
  test('same agent prompt → true', () => {
    expect(
      isHookEqual(
        { type: 'agent', prompt: 'find bugs' } as Hook,
        { type: 'agent', prompt: 'find bugs' } as Hook,
      ),
    ).toBe(true)
  })

  test('different agent prompts → false', () => {
    expect(
      isHookEqual(
        { type: 'agent', prompt: 'a' } as Hook,
        { type: 'agent', prompt: 'b' } as Hook,
      ),
    ).toBe(false)
  })
})

describe('isHookEqual — http type', () => {
  test('same url → true', () => {
    expect(
      isHookEqual(
        { type: 'http', url: 'https://example.com/hook' } as Hook,
        { type: 'http', url: 'https://example.com/hook' } as Hook,
      ),
    ).toBe(true)
  })

  test('different urls → false', () => {
    expect(
      isHookEqual(
        { type: 'http', url: 'https://a.example.com' } as Hook,
        { type: 'http', url: 'https://b.example.com' } as Hook,
      ),
    ).toBe(false)
  })

  test('same url different `if` → false', () => {
    expect(
      isHookEqual(
        { type: 'http', url: 'https://x.com', if: 'a' } as Hook,
        { type: 'http', url: 'https://x.com', if: 'b' } as Hook,
      ),
    ).toBe(false)
  })
})

describe('isHookEqual — function type (always false)', () => {
  test('two function hooks with same shape → false', () => {
    // Documented: function hooks can't be compared (no stable
    // identifier). Two registrations of the "same" function are
    // treated as distinct.
    expect(
      isHookEqual(
        { type: 'function', timeout: 1000 } as Hook,
        { type: 'function', timeout: 1000 } as Hook,
      ),
    ).toBe(false)
  })

  test('function hook compared to itself → still false', () => {
    const fn = { type: 'function' } as Hook
    expect(isHookEqual(fn, fn)).toBe(false)
  })
})

describe('isHookEqual — return shape', () => {
  test('always returns boolean', () => {
    const samples: Array<[Hook, Hook]> = [
      [{ type: 'command', command: 'a' } as Hook, { type: 'command', command: 'a' } as Hook],
      [{ type: 'prompt', prompt: 'a' } as Hook, { type: 'agent', prompt: 'a' } as Hook],
      [{ type: 'function' } as Hook, { type: 'function' } as Hook],
    ]
    for (const [a, b] of samples) {
      expect(typeof isHookEqual(a, b)).toBe('boolean')
    }
  })
})

import { afterEach, describe, expect, test } from 'bun:test'
import {
  canYankPop,
  clearKillRing,
  getKillRingItem,
  getKillRingSize,
  getLastKill,
  pushToKillRing,
  recordYank,
  resetKillAccumulation,
  updateYankLength,
  yankPop,
} from '../Cursor.js'

afterEach(() => {
  clearKillRing()
  resetKillAccumulation()
})

describe('kill ring', () => {
  test('pushToKillRing stores text', () => {
    pushToKillRing('hello')
    expect(getLastKill()).toBe('hello')
    expect(getKillRingSize()).toBe(1)
  })

  test('consecutive kills accumulate', () => {
    pushToKillRing('hello ')
    pushToKillRing('world')
    expect(getLastKill()).toBe('hello world')
    expect(getKillRingSize()).toBe(1)
  })

  test('prepend direction inserts at front of accumulated kill', () => {
    pushToKillRing('world')
    pushToKillRing('hello ', 'prepend')
    expect(getLastKill()).toBe('hello world')
  })

  test('resetKillAccumulation breaks the chain', () => {
    pushToKillRing('first')
    resetKillAccumulation()
    pushToKillRing('second')
    expect(getLastKill()).toBe('second')
    expect(getKillRingSize()).toBe(2)
    expect(getKillRingItem(1)).toBe('first')
  })

  test('empty text is ignored', () => {
    pushToKillRing('')
    expect(getKillRingSize()).toBe(0)
  })

  test('ring caps at MAX_SIZE 10 — older entries fall off', () => {
    for (let i = 0; i < 15; i++) {
      pushToKillRing(`kill-${i}`)
      resetKillAccumulation()
    }
    expect(getKillRingSize()).toBe(10)
    expect(getLastKill()).toBe('kill-14')
    // Oldest retained is kill-5 (since 0..4 fell off)
    expect(getKillRingItem(9)).toBe('kill-5')
  })

  test('getKillRingItem normalizes negative + out-of-range indices', () => {
    pushToKillRing('a')
    resetKillAccumulation()
    pushToKillRing('b')
    resetKillAccumulation()
    pushToKillRing('c')
    // Most recent is 'c', then 'b', then 'a'
    expect(getKillRingItem(0)).toBe('c')
    expect(getKillRingItem(1)).toBe('b')
    expect(getKillRingItem(2)).toBe('a')
    // wraps around
    expect(getKillRingItem(3)).toBe('c')
    // negative wraps too
    expect(getKillRingItem(-1)).toBe('a')
  })

  test('clearKillRing empties everything', () => {
    pushToKillRing('a')
    resetKillAccumulation()
    pushToKillRing('b')
    clearKillRing()
    expect(getKillRingSize()).toBe(0)
    expect(getLastKill()).toBe('')
  })
})

describe('yank tracking', () => {
  test('canYankPop is false until a yank is recorded', () => {
    pushToKillRing('a')
    resetKillAccumulation()
    pushToKillRing('b')
    expect(canYankPop()).toBe(false)
  })

  test('canYankPop becomes true after recordYank', () => {
    pushToKillRing('a')
    resetKillAccumulation()
    pushToKillRing('b')
    recordYank(0, 1)
    expect(canYankPop()).toBe(true)
  })

  test('canYankPop is false when ring has only one entry', () => {
    pushToKillRing('a')
    recordYank(0, 1)
    expect(canYankPop()).toBe(false)
  })

  test('yankPop returns previous entries and tracks position', () => {
    pushToKillRing('a')
    resetKillAccumulation()
    pushToKillRing('b')
    resetKillAccumulation()
    pushToKillRing('c')
    recordYank(0, 1)
    const popped1 = yankPop()
    if (popped1 === null) throw new Error('yankPop returned null')
    expect(popped1.text).toBe('b')
    const popped2 = yankPop()
    if (popped2 === null) throw new Error('yankPop returned null')
    expect(popped2.text).toBe('a')
  })

  test('updateYankLength affects subsequent yankPop replacement range', () => {
    pushToKillRing('aa')
    resetKillAccumulation()
    pushToKillRing('bbbb')
    recordYank(5, 2)
    updateYankLength(4) // simulate yank insertion of 'bbbb'
    const popped = yankPop()
    if (popped === null) throw new Error('yankPop returned null')
    // length-replacement window now covers the 4 we typed
    expect(popped.start).toBe(5)
    expect(popped.length).toBe(4)
  })

  test('pushing a new kill clears yank state', () => {
    pushToKillRing('a')
    resetKillAccumulation()
    pushToKillRing('b')
    recordYank(0, 1)
    expect(canYankPop()).toBe(true)
    pushToKillRing('c')
    expect(canYankPop()).toBe(false)
  })
})
